import { cn } from '../../lib/utils';
import { MasanLogoIcon } from './masan-logo';

interface GlobalLoadingProps {
  className?: string;
  text?: string;
}

export function GlobalLoading({ className, text }: GlobalLoadingProps) {
  return (
    <div
      className={cn('flex h-screen w-full flex-col items-center justify-center gap-4', className)}
    >
      <div className="relative">
        <MasanLogoIcon className="size-20 animate-pulse text-primary" />
        <div className="absolute inset-0 animate-ping">
          <MasanLogoIcon className="size-20 text-primary opacity-75" />
        </div>
      </div>
      {text && <p className="animate-pulse font-medium text-muted-foreground text-sm">{text}</p>}
    </div>
  );
}

import type { ImgHTMLAttributes } from 'react';
import { cn } from '../../lib/utils';

export function MasanLogo({ className, ...props }: ImgHTMLAttributes<HTMLImageElement>) {
  return (
    <>
      <img
        src="/logo-masan.png"
        alt="Masan Group"
        className={cn('h-12 w-auto dark:hidden', className)}
        {...props}
      />
      <img
        src="/logo-masan-dark.png"
        alt="Masan Group"
        className={cn('hidden h-14 w-auto dark:block', className)}
        {...props}
      />
    </>
  );
}

// Icon version for sidebar (smaller, square aspect ratio)
export function MasanLogoIcon({ className, ...props }: ImgHTMLAttributes<HTMLImageElement>) {
  return (
    <>
      <img
        src="/logo-icon.png"
        alt="Masan"
        className={cn('size-5 object-contain dark:hidden', className)}
        {...props}
      />
      <img
        src="/logo-icon-dark.png"
        alt="Masan Group"
        className={cn('hidden size-5 object-contain dark:block', className)}
        {...props}
      />
    </>
  );
}

import type * as React from 'react';

import { CHART_THEME } from '../utils/chart-theme';
import { cn } from '../../../../lib/utils';
import type { BaseChartProps } from '../types/chart-types';
import { type ChartConfig, ChartContainer } from '../../../ui/display/chart';
import { EmptyState } from '../../../ui/feedback/empty-state';
import MLChartLoading from '../../ml-chart-loading/component';

/**
 * Props for ChartWrapper component
 */
export interface ChartWrapperProps extends BaseChartProps {
  /** Chart configuration for colors and labels */
  config: ChartConfig;
  /** Chart content - must be a Recharts chart component */
  children: React.ReactElement;
}

/**
 * ChartWrapper Component
 *
 * Provides consistent loading, error, and empty states for all charts.
 * Automatically applies CHART_THEME height tokens and integrates with ChartContainer.
 *
 * @example
 * ```tsx
 * <ChartWrapper
 *   config={chartConfig}
 *   height="lg"
 *   loading={isLoading}
 *   error={error}
 *   empty={!data.length}
 * >
 *   <LineChart data={data}>...</LineChart>
 * </ChartWrapper>
 * ```
 */
export function ChartWrapper({
  children,
  config,
  height = 'lg',
  loading,
  error,
  empty,
  className,
}: ChartWrapperProps) {
  // Show loading state
  if (loading) {
    return <MLChartLoading variant="wave" chartHeight={height} />;
  }

  // Show error state
  if (error) {
    return <EmptyState variant="error" size="lg" />;
  }

  // Show empty state (no data)
  if (empty) {
    return <EmptyState variant="chart" size="lg" />;
  }

  // Resolve height class from CHART_THEME or use custom value
  const heightClass =
    typeof height === 'string' && height in CHART_THEME.heights
      ? CHART_THEME.heights[height as keyof typeof CHART_THEME.heights]
      : height;

  return (
    <ChartContainer config={config} className={cn(heightClass, 'w-full', className)}>
      {children}
    </ChartContainer>
  );
}

import type * as React from 'react';
import type { Payload } from 'recharts/types/component/DefaultTooltipContent';
import type { NameType, ValueType } from 'recharts/types/component/DefaultTooltipContent';
import type { TimeGranularity } from '../../../../types/date';
import type { UOM } from '../../../../types/uom';
import type { ChartFormattingAdapter } from '../types/chart-formatting';
import { defaultChartFormattingAdapter } from '../types/chart-formatting';

/**
 * Chart formatter functions
 */
export interface ChartFormatters {
  /** Format X-axis labels (dates/periods) */
  xAxisFormatter: (value: string | number) => string;
  /** Format Y-axis labels (values with units) */
  yAxisFormatter: (value: number) => string;
  /** Format tooltip labels (detailed dates) - for ChartTooltipContent labelFormatter prop */
  tooltipLabelFormatter: (
    value: NameType,
    payload: Payload<ValueType, NameType>[]
  ) => React.ReactNode;
  /** Format tooltip values (numbers with UOM) - for ChartTooltipContent formatter prop */
  tooltipValueFormatter: (
    value: ValueType,
    name: NameType,
    item: Payload<ValueType, NameType>,
    index: number,
    payload: Payload<ValueType, NameType>[]
  ) => React.ReactNode;
}

/**
 * Hook to get chart formatters based on time granularity and unit of measure
 *
 * @param timeGranularity - Time granularity for date formatting
 * @param uom - Unit of measure for value formatting
 * @param formattingAdapter - Optional adapter to override default formatting behavior
 * @returns Chart formatter functions
 */
export function useChartFormatter(
  timeGranularity?: TimeGranularity,
  _uom?: UOM,
  formattingAdapter?: Partial<ChartFormattingAdapter>
): ChartFormatters {
  const adapter: ChartFormattingAdapter = {
    ...defaultChartFormattingAdapter,
    ...formattingAdapter,
  };

  const xAxisFormatter = (value: string | number): string => {
    return adapter.xAxisFormatter(value, timeGranularity);
  };

  const yAxisFormatter = (value: number): string => {
    return adapter.yAxisFormatter(value);
  };

  const tooltipLabelFormatter = (
    value: NameType,
    payload: Payload<ValueType, NameType>[]
  ): React.ReactNode => {
    return adapter.tooltipLabelFormatter(value, payload, timeGranularity);
  };

  const tooltipValueFormatter = (
    value: ValueType,
    name: NameType,
    item: Payload<ValueType, NameType>,
    _index: number,
    _payload: Payload<ValueType, NameType>[]
  ): React.ReactNode => {
    return adapter.tooltipValueFormatter(value, name, item, _index, _payload);
  };

  return {
    xAxisFormatter,
    yAxisFormatter,
    tooltipLabelFormatter,
    tooltipValueFormatter,
  };
}

/**
 * Hook to get responsive chart height based on viewport
 * Automatically adjusts chart height for mobile, tablet, desktop
 *
 * @returns Current chart height class
 */
export function useChartResponsive(): 'sm' | 'md' | 'lg' {
  // Will be implemented with window resize listener
  // For now, returns default
  return 'lg';
}

export { CHART_THEME } from './utils/chart-theme';
export type { ChartHeight, ChartMarginPreset } from './utils/chart-theme';

// Types
export type {
  BaseChartProps,
  ChartAxisProps,
  ChartDataPoint,
  ChartMargin,
  ChartInteractionProps,
  ChartContainerProps,
} from './types/chart-types';

// Hooks
export { useChartFormatter, useChartResponsive } from './hooks/use-chart-formatter';
export type { ChartFormatters } from './hooks/use-chart-formatter';

// Base components
export { ChartWrapper } from './base/chart-wrapper';
export type { ChartWrapperProps } from './base/chart-wrapper';
export { ChartLegend, ChartLegendContent } from '../../ui';

// UI chart primitives
export { ChartContainer, ChartTooltip, ChartTooltipContent } from '../../ui/display/chart';
export type { ChartConfig } from '../../ui/display/chart';

// Re-export color system from shared-ui root
export {
  CHART_COLORS,
  CHART_PALETTE,
  CHART_SEMANTIC_COLORS,
  COLOR_MIGRATION_MAP,
  getChartColor,
  convertHslToOklch,
} from './utils/chart-colors';
export type {
  ChartColor,
  ChartPaletteColor,
  ChartSemanticColor,
} from './utils/chart-colors';

import type * as React from 'react';
import type { Payload, NameType, ValueType } from 'recharts/types/component/DefaultTooltipContent';
import { formatXAxisLabel } from '../utils/format-x-axis-label';
import { formatDetailedDate } from '../../../../utils/date-formatting';
import { formatCompact } from '../../../../utils/number-formatting';
import type { TimeGranularity } from '../../../../types/date';

export interface ChartFormattingAdapter {
  xAxisFormatter: (value: string | number, granularity?: TimeGranularity) => string;
  yAxisFormatter: (value: number) => string;
  tooltipLabelFormatter: (
    value: NameType,
    payload: Payload<ValueType, NameType>[],
    granularity?: TimeGranularity
  ) => React.ReactNode;
  tooltipValueFormatter: (
    value: ValueType,
    name: NameType,
    item: Payload<ValueType, NameType>,
    index: number,
    payload: Payload<ValueType, NameType>[]
  ) => React.ReactNode;
}

export const defaultChartFormattingAdapter: ChartFormattingAdapter = {
  xAxisFormatter: (value, granularity) =>
    granularity ? formatXAxisLabel(String(value), granularity) : String(value),

  yAxisFormatter: (value) => {
    if (!value && value !== 0) return '';
    return formatCompact(value, 1);
  },

  tooltipLabelFormatter: (value, payload, granularity) => {
    if (!granularity) return String(value);
    const timestamp = payload?.[0]?.payload?.timestamp ?? value;
    return formatDetailedDate(String(timestamp), granularity);
  },

  tooltipValueFormatter: (value, name, item, _index, _payload) => {
    const rawValue = Array.isArray(value) ? value[0] : value;
    const numericValue = rawValue == null ? 0 : Number(rawValue);
    const formattedValue = formatCompact(numericValue, 2);
    const color = item?.color || item?.payload?.fill || item?.stroke;

    return (
      <>
        <span className="text-muted-foreground" style={{ color }}>
          {name}:
        </span>
        <span className="pl-3 font-medium font-mono text-foreground tabular-nums">
          {formattedValue}
        </span>
      </>
    );
  },
};

import type * as React from 'react';
import type { UOM } from '../../../../types/uom';
import type { TimeGranularity } from '../../../../types/date';
import type { ChartHeight, ChartMarginPreset } from '../utils/chart-theme';

/**
 * Chart margin configuration
 * Compatible with Recharts margin prop
 */
export type ChartMargin = {
  top?: number;
  right?: number;
  bottom?: number;
  left?: number;
};

/**
 * Base props shared by all chart components
 */
export interface BaseChartProps {
  /** Chart height - semantic token or custom CSS class */
  height?: ChartHeight | string;
  /** Chart margin - preset or custom object */
  margin?: ChartMarginPreset | ChartMargin;
  /** Loading state */
  loading?: boolean;
  /** Error state */
  error?: Error | null;
  /** Empty state (no data) */
  empty?: boolean;
  /** Additional CSS classes */
  className?: string;
}

/**
 * Chart axis configuration props
 */
export interface ChartAxisProps {
  /** Time granularity for X-axis labels */
  timeGranularity?: TimeGranularity;
  /** Unit of measure for Y-axis labels */
  uom?: UOM;
  /** Show grid lines */
  showGrid?: boolean;
  /** Show X-axis */
  showXAxis?: boolean;
  /** Show Y-axis */
  showYAxis?: boolean;
  /** Custom X-axis tick formatter (overrides default timeGranularity formatting) */
  xAxisFormatter?: (value: string | number) => string;
  /** Custom Y-axis tick formatter (overrides default UOM formatting) */
  yAxisFormatter?: (value: number) => string;
}

/**
 * Generic chart data point
 * Flexible structure for various chart types
 */
export interface ChartDataPoint {
  [key: string]: string | number | Date | null | undefined;
}

/**
 * Common chart interaction props
 */
export interface ChartInteractionProps {
  /** Show tooltip on hover */
  showTooltip?: boolean;
  /** Show legend */
  showLegend?: boolean;
  /** Enable brush for zooming */
  showBrush?: boolean;
  /** Custom tooltip formatter */
  tooltipFormatter?: (value: any, name: string) => React.ReactNode;
  /** Custom label formatter (receives string | number from Recharts tooltip) */
  labelFormatter?: (label: string | number, payload?: any) => string;
}

/**
 * Chart container props
 * Combines all common props
 */
export interface ChartContainerProps extends BaseChartProps, ChartAxisProps, ChartInteractionProps {
  /** Chart data */
  data: ChartDataPoint[];
  /** Chart configuration for colors/labels */
  config: Record<string, { label?: string; color?: string }>;
}

export const CHART_COLORS = {
  // Semantic names (recommended)
  PRIMARY: 'oklch(0.6242 0.1822 259.6956)',
  SECONDARY: 'oklch(0.6500 0.1800 145.0000)',
  TERTIARY: 'oklch(0.7200 0.1900 65.0000)',
  QUATERNARY: 'oklch(0.6200 0.2200 25.0000)',
  ACCENT: 'oklch(0.5464 0.2096 262.9482)',
  MUTED: 'oklch(0.9687 0.0030 264.5400)',

  // Explicit color names (aliases for clarity)
  BLUE: 'oklch(0.6242 0.1822 259.6956)',
  GREEN: 'oklch(0.6500 0.1800 145.0000)',
  ORANGE: 'oklch(0.7200 0.1900 65.0000)',
  RED: 'oklch(0.6200 0.2200 25.0000)',
  PURPLE: 'oklch(0.5464 0.2096 262.9482)',
} as const;

/**
 * Extended color palette for multi-series charts
 * 24 distinguishable colors for complex visualizations
 */
export const CHART_PALETTE = [
  // Primary (from CHART_COLORS)
  'oklch(0.6242 0.1822 259.6956)', // Blue
  'oklch(0.6500 0.1800 145.0000)', // Green
  'oklch(0.7200 0.1900 65.0000)', // Orange
  'oklch(0.6200 0.2200 25.0000)', // Red
  'oklch(0.5464 0.2096 262.9482)', // Purple

  // Secondary
  'oklch(0.7000 0.1500 200.0000)', // Cyan
  'oklch(0.6500 0.2000 330.0000)', // Pink
  'oklch(0.7500 0.1600 100.0000)', // Lime
  'oklch(0.5800 0.1800 280.0000)', // Indigo
  'oklch(0.7200 0.1400 180.0000)', // Teal

  // Tertiary
  'oklch(0.6800 0.1700 50.0000)', // Amber
  'oklch(0.6000 0.2100 310.0000)', // Fuchsia
  'oklch(0.7000 0.1300 220.0000)', // Sky
  'oklch(0.6500 0.1900 350.0000)', // Rose
  'oklch(0.7300 0.1500 120.0000)', // Emerald

  // Quaternary
  'oklch(0.5500 0.1600 270.0000)', // Violet
  'oklch(0.7100 0.1800 40.0000)', // Yellow-Orange
  'oklch(0.6300 0.1400 240.0000)', // Slate Blue
  'oklch(0.6800 0.2000 20.0000)', // Coral
  'oklch(0.7400 0.1200 160.0000)', // Mint

  // Additional
  'oklch(0.5900 0.1700 300.0000)', // Orchid
  'oklch(0.6700 0.1600 80.0000)', // Gold
  'oklch(0.6100 0.1500 250.0000)', // Periwinkle
  'oklch(0.7200 0.1700 10.0000)', // Salmon
] as const;

/**
 * Get chart color by index
 * Uses CHART_PALETTE for indices 0-23, generates new color beyond
 *
 * @param index - Zero-based index
 * @returns oklch color string
 */
export function getChartColor(index: number): string {
  if (index >= 0 && index < CHART_PALETTE.length) {
    return CHART_PALETTE[index] as string;
  }

  // Generate additional colors using golden angle distribution
  const hue = (index * 137.5) % 360;
  const lightness = 0.6 + (index % 3) * 0.05;
  const chroma = 0.15 + (index % 2) * 0.05;

  return `oklch(${lightness.toFixed(4)} ${chroma.toFixed(4)} ${hue.toFixed(4)})`;
}

/**
 * Semantic chart colors for data states and regions
 * All colors in OKLCH format for consistency
 * Replaces legacy HSL colors from forecast-chart-utils.ts
 */
export const CHART_SEMANTIC_COLORS = {
  // Data states
  /** Historical/actual data - Purple */
  ACTUAL: 'oklch(0.6300 0.1900 290.0000)',
  /** Forecast data - Gray */
  FORECAST: 'oklch(0.6000 0.0500 264.5400)',
  /** Comparison overlay - Purple (matches ACTUAL) */
  COMPARISON: 'oklch(0.6300 0.1900 290.0000)',

  // Regional colors (converted from HSL)
  /** North region - Blue */
  NORTH: 'oklch(0.5800 0.1900 260.0000)',
  /** Central region - Green */
  CENTRAL: 'oklch(0.5500 0.1600 150.0000)',
  /** South region - Orange */
  SOUTH: 'oklch(0.7000 0.1800 55.0000)',

  // Status indicators
  /** Positive/success state - Green */
  POSITIVE: 'oklch(0.6500 0.1800 145.0000)',
  /** Negative/error state - Red */
  NEGATIVE: 'oklch(0.6200 0.2200 25.0000)',
  /** Neutral state - Gray */
  NEUTRAL: 'oklch(0.6000 0.0500 264.5400)',
} as const;

/**
 * HSL to OKLCH color migration mapping
 * @deprecated Use CHART_SEMANTIC_COLORS instead
 * Legacy HSL colors from forecast-chart-utils.ts
 */
export const COLOR_MIGRATION_MAP = {
  // Old HSL → New OKLCH
  'hsl(272 77% 55%)': CHART_SEMANTIC_COLORS.ACTUAL,
  'hsl(0 0% 50%)': CHART_SEMANTIC_COLORS.FORECAST,
  'hsl(221 83% 53%)': CHART_SEMANTIC_COLORS.NORTH,
  'hsl(142 76% 36%)': CHART_SEMANTIC_COLORS.CENTRAL,
  'hsl(38 92% 50%)': CHART_SEMANTIC_COLORS.SOUTH,
} as const;

/**
 * Convert legacy HSL color to OKLCH equivalent
 * @param hslColor - HSL color string
 * @returns OKLCH color string or original if no mapping
 * @deprecated Migrate to CHART_SEMANTIC_COLORS directly
 */
export function convertHslToOklch(hslColor: string): string {
  return COLOR_MIGRATION_MAP[hslColor as keyof typeof COLOR_MIGRATION_MAP] || hslColor;
}

/** Type for CHART_COLORS values */
export type ChartColor = (typeof CHART_COLORS)[keyof typeof CHART_COLORS];

/** Type for CHART_PALETTE values */
export type ChartPaletteColor = (typeof CHART_PALETTE)[number];

/** Type for CHART_SEMANTIC_COLORS values */
export type ChartSemanticColor = (typeof CHART_SEMANTIC_COLORS)[keyof typeof CHART_SEMANTIC_COLORS];

import type { ChartMargin } from '../types/chart-types';

/**
 * Chart theme configuration
 * All values follow design system standards
 */
export const CHART_THEME = {
  /**
   * Standard chart heights
   * Use semantic names for consistency
   */
  heights: {
    sm: 'h-[200px]',
    md: 'h-[300px]',
    lg: 'h-[400px]',
    xl: 'h-[500px]',
  },

  /**
   * Chart margins (Recharts format)
   * Controls spacing around chart area
   *
   * Note: Left margin prevents Y-axis label truncation
   * Values follow design system 8px spacing grid
   */
  margins: {
    /** Standard margin for most charts */
    default: { top: 16, right: 16, left: 16, bottom: 8 } as ChartMargin,
    /** Compact margin for dense layouts */
    compact: { top: 8, right: 8, left: 12, bottom: 0 } as ChartMargin,
    /** Spacious margin for featured charts */
    spacious: { top: 24, right: 24, left: 24, bottom: 8 } as ChartMargin,
  },

  /**
   * Typography settings for chart elements
   */
  typography: {
    /** Axis labels (X, Y) */
    axis: {
      fontSize: 12,
      fontFamily: 'inherit',
    },
    /** Tooltip content */
    tooltip: {
      fontSize: 13,
      fontFamily: 'inherit',
    },
    /** Legend labels */
    legend: {
      fontSize: 12,
      fontFamily: 'inherit',
    },
  },

  /**
   * Grid styling
   */
  grid: {
    /** Dashed line pattern */
    strokeDasharray: '4 4 4',
    /** Grid line opacity */
    strokeOpacity: 1,
    /** Grid line color */
    stroke: '#e2e8f0',
  },

  /**
   * Animation settings
   */
  animations: {
    /** Animation duration in milliseconds */
    duration: 300,
    /** Easing function */
    easing: 'ease-in-out' as const,
  },
} as const;

/**
 * Type for chart height keys
 */
export type ChartHeight = keyof typeof CHART_THEME.heights;

/**
 * Type for chart margin presets
 */
export type ChartMarginPreset = keyof typeof CHART_THEME.margins;

import { getISOWeek, getISOWeekYear } from 'date-fns';

/**
 * Format timestamp to readable label based on time granularity
 */
export function formatXAxisLabel(timestamp: string, timeGranularity = 'week'): string {
  const date = new Date(timestamp);
  if (Number.isNaN(date.getTime())) return timestamp;

  switch (timeGranularity) {
    case 'day':
      return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
    case 'week': {
      const week = getISOWeek(date);
      const year = getISOWeekYear(date);
      const shortYear = year.toString().slice(-2);
      return `W${week.toString().padStart(2, '0')}/${shortYear}`;
    }
    case 'month': {
      const month = date.getMonth() + 1; // getMonth() returns 0-11
      const year = date.getFullYear().toString().slice(-2);
      return `M${month}/${year}`;
    }
    case 'year':
      return date.getFullYear().toString();
    default:
      return date.toLocaleDateString('en-US', { month: 'short', year: '2-digit' });
  }
}

import type { Table } from '@tanstack/react-table';
import { X } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';
import { Badge } from '../../ui/display/badge';
import { Button } from '../../ui/actions/button';
import { Separator } from '../../ui/display/separator';
import { Tooltip, TooltipContent, TooltipTrigger } from '../../ui/overlays/tooltip';
import { cn } from '../../../lib/utils';

type DataTableBulkActionsProps<TData> = {
  table: Table<TData>;
  entityName: string;
  children: React.ReactNode;
};

/**
 * A modular toolbar for displaying bulk actions when table rows are selected.
 *
 * @template TData The type of data in the table.
 * @param {object} props The component props.
 * @param {Table<TData>} props.table The react-table instance.
 * @param {string} props.entityName The name of the entity being acted upon (e.g., "task", "user").
 * @param {React.ReactNode} props.children The action buttons to be rendered inside the toolbar.
 * @returns {React.ReactNode | null} The rendered component or null if no rows are selected.
 */
export function DataTableBulkActions<TData>({
  table,
  entityName,
  children,
}: DataTableBulkActionsProps<TData>): React.ReactNode | null {
  const selectedRows = table.getFilteredSelectedRowModel().rows;
  const selectedCount = selectedRows.length;
  const toolbarRef = useRef<HTMLDivElement>(null);
  const [announcement, setAnnouncement] = useState('');

  // Announce selection changes to screen readers
  useEffect(() => {
    if (selectedCount > 0) {
      const message = `${selectedCount} ${entityName}${selectedCount > 1 ? 's' : ''} selected. Bulk actions toolbar is available.`;

      // Use queueMicrotask to defer state update and avoid cascading renders
      queueMicrotask(() => {
        setAnnouncement(message);
      });

      // Clear announcement after a delay
      const timer = setTimeout(() => setAnnouncement(''), 3000);
      return () => clearTimeout(timer);
    }
  }, [selectedCount, entityName]);

  const handleClearSelection = () => {
    table.resetRowSelection();
  };

  const handleKeyDown = (event: React.KeyboardEvent) => {
    const buttons = toolbarRef.current?.querySelectorAll('button');
    if (!buttons) return;

    const currentIndex = Array.from(buttons).indexOf(document.activeElement as HTMLButtonElement);

    switch (event.key) {
      case 'ArrowRight': {
        event.preventDefault();
        const nextIndex = (currentIndex + 1) % buttons.length;
        buttons[nextIndex]?.focus();
        break;
      }
      case 'ArrowLeft': {
        event.preventDefault();
        const prevIndex = currentIndex === 0 ? buttons.length - 1 : currentIndex - 1;
        buttons[prevIndex]?.focus();
        break;
      }
      case 'Home':
        event.preventDefault();
        buttons[0]?.focus();
        break;
      case 'End':
        event.preventDefault();
        buttons[buttons.length - 1]?.focus();
        break;
      case 'Escape': {
        // Check if the Escape key came from a dropdown trigger or content
        // We can't check dropdown state because Radix UI closes it before our handler runs
        const target = event.target as HTMLElement;
        const activeElement = document.activeElement as HTMLElement;

        // Check if the event target or currently focused element is a dropdown trigger
        const isFromDropdownTrigger =
          target?.getAttribute('data-slot') === 'dropdown-menu-trigger' ||
          activeElement?.getAttribute('data-slot') === 'dropdown-menu-trigger' ||
          target?.closest('[data-slot="dropdown-menu-trigger"]') ||
          activeElement?.closest('[data-slot="dropdown-menu-trigger"]');

        // Check if the focused element is inside dropdown content (which is portaled)
        const isFromDropdownContent =
          activeElement?.closest('[data-slot="dropdown-menu-content"]') ||
          target?.closest('[data-slot="dropdown-menu-content"]');

        if (isFromDropdownTrigger || isFromDropdownContent) {
          // Escape was meant for the dropdown - don't clear selection
          return;
        }

        // Escape was meant for the toolbar - clear selection
        event.preventDefault();
        handleClearSelection();
        break;
      }
    }
  };

  if (selectedCount === 0) {
    return null;
  }

  return (
    <>
      {/* Live region for screen reader announcements */}
      <output aria-live="polite" aria-atomic="true" className="sr-only">
        {announcement}
      </output>

      <div
        ref={toolbarRef}
        role="toolbar"
        aria-label={`Bulk actions for ${selectedCount} selected ${entityName}${selectedCount > 1 ? 's' : ''}`}
        aria-describedby="bulk-actions-description"
        tabIndex={-1}
        onKeyDown={handleKeyDown}
        className={cn(
          'fixed bottom-6 left-1/2 z-50 -translate-x-1/2 rounded-xl',
          'transition-all delay-100 duration-300 ease-out hover:scale-105',
          'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50'
        )}
      >
        <div
          className={cn(
            'p-2 shadow-xl',
            'rounded-xl border',
            'bg-background/95 backdrop-blur-lg supports-[backdrop-filter]:bg-background/60',
            'flex items-center gap-x-2'
          )}
        >
          <Tooltip>
            <TooltipTrigger asChild>
              <Button
                variant="outline"
                size="icon"
                onClick={handleClearSelection}
                className="size-6 rounded-full"
                aria-label="Clear selection"
                title="Clear selection (Escape)"
              >
                <X />
                <span className="sr-only">Clear selection</span>
              </Button>
            </TooltipTrigger>
            <TooltipContent>
              <p>Clear selection (Escape)</p>
            </TooltipContent>
          </Tooltip>

          <Separator className="h-5" orientation="vertical" aria-hidden="true" />

          <div className="flex items-center gap-x-1 text-sm" id="bulk-actions-description">
            <Badge
              variant="primary"
              className="min-w-8 rounded-lg"
              aria-label={`${selectedCount} selected`}
            >
              {selectedCount}
            </Badge>
            <span className="hidden sm:inline">
              {entityName}
              {selectedCount > 1 ? 's' : ''}
            </span>
            selected
          </div>

          <Separator className="h-5" orientation="vertical" aria-hidden="true" />

          {children}
        </div>
      </div>
    </>
  );
}

import { ArrowDownIcon, ArrowUpIcon, CaretSortIcon, EyeNoneIcon } from '@radix-ui/react-icons';
import type { Column } from '@tanstack/react-table';
import { Button } from '../../ui/actions/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '../../ui/actions/dropdown-menu';
import { cn } from '../../../lib/utils';

type DataTableColumnHeaderProps<TData, TValue> = React.HTMLAttributes<HTMLDivElement> & {
  column: Column<TData, TValue>;
  title: string;
};

export function DataTableColumnHeader<TData, TValue>({
  column,
  title,
  className,
}: DataTableColumnHeaderProps<TData, TValue>) {
  if (!column.getCanSort()) {
    return <div className={cn(className)}>{title}</div>;
  }

  return (
    <div className={cn('flex items-center space-x-2', className)}>
      <DropdownMenu>
        <DropdownMenuTrigger
          render={(props) => (
            <Button
              {...props}
              variant="ghost"
              size="sm"
              className="h-8 data-[state=open]:bg-accent"
            >
              <span>{title}</span>
              {column.getIsSorted() === 'desc' ? (
                <ArrowDownIcon className="ms-2 h-4 w-4" />
              ) : column.getIsSorted() === 'asc' ? (
                <ArrowUpIcon className="ms-2 h-4 w-4" />
              ) : (
                <CaretSortIcon className="ms-2 h-4 w-4" />
              )}
            </Button>
          )}
        />
        <DropdownMenuContent align="start">
          <DropdownMenuItem onClick={() => column.toggleSorting(false)}>
            <ArrowUpIcon className="size-3.5 text-muted-foreground/70" />
            Asc
          </DropdownMenuItem>
          <DropdownMenuItem onClick={() => column.toggleSorting(true)}>
            <ArrowDownIcon className="size-3.5 text-muted-foreground/70" />
            Desc
          </DropdownMenuItem>
          {column.getCanHide() && (
            <>
              <DropdownMenuSeparator />
              <DropdownMenuItem onClick={() => column.toggleVisibility(false)}>
                <EyeNoneIcon className="size-3.5 text-muted-foreground/70" />
                Hide
              </DropdownMenuItem>
            </>
          )}
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
}

import {
  type ColumnDef,
  getCoreRowModel,
  getFacetedRowModel,
  getFacetedUniqueValues,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  type OnChangeFn,
  type SortingState,
  type Table as TanStackTable,
  useReactTable,
  type Row,
  type ColumnSizingState,
} from '@tanstack/react-table';
import type { UseTableUrlStateReturn } from '../../../hooks/use-table-url-state';
import { useState } from 'react';
import { useColumnVisibility } from './view-options/user-view-options-storage';
import { Table } from '../../ui/display/table';
import { useFullHeightTable } from '../../../hooks/use-full-height-table';
import { cn } from '../../../lib/utils';
import { DataTablePagination } from './table-pagination';
