export type DataTableFilterOption = {
  columnId: string;
  title: string;
  name?: string;
  options: {
    label: string;
    value: string;
    icon?: React.ComponentType<{ className?: string }>;
  }[];
};

type DataTableProps<TData, TValue> = {
  /**
   * The data to display in the table
   */
  data: TData[];

  /**
   * The column definitions for the table
   */
  columns: ColumnDef<TData, TValue>[];

  /**
   * Placeholder text for the search input
   * @default "Filter..."
   */
  searchPlaceholder?: string;

  /**
   * The key to use for searching (if using column-specific search)
   * If not provided, will use global filter
   */
  searchKey?: string;

  /**
   * Filter configurations for faceted filters
   */
  filters?: DataTableFilterOption[];

  /**
   * URL state management (optional)
   * If provided, table state will be synced with URL params
   */
  urlState?: Omit<UseTableUrlStateReturn, 'ensurePageInRange'>;

  /**
   * Custom global filter function
   */
  globalFilterFn?: (row: Row<TData>, columnId: string, filterValue: unknown) => boolean;

  /**
   * Enable sticky header
   * @default true
   */
  stickyHeader?: boolean;

  /**
   * Enable full height calculation with scrolling
   * @default true
   */
  enableFullHeight?: boolean;

  /**
   * Minimum height for the table (when enableFullHeight is true)
   * @default 400
   */
  minHeight?: number;

  /**
   * Bottom offset for height calculation (e.g., pagination height)
   * @default 80
   */
  bottomOffset?: number;

  /**
   * Default page size
   * @default 10
   */
  defaultPageSize?: number;

  /**
   * Additional className for the container
   */
  className?: string;

  /**
   * Additional className for the table wrapper
   */
  tableClassName?: string;

  /**
   * Render prop for bulk actions when rows are selected
   * Receives the table instance as parameter
   */
  bulkActions?: (table: TanStackTable<TData>) => React.ReactNode;

  /**
   * Show view options
   * @default true
   */
  showViewOptions?: boolean;

  /**
   * Loading state for async data
   * @default false
   */
  loading?: boolean;

  /**
   * Number of skeleton rows to show when loading
   * @default 5
   */
  skeletonRows?: number;

  /**
   * Enable manual pagination (server-side)
   * @default false
   */
  manualPagination?: boolean;

  /**
   * Total page count for manual pagination
   * If totalCount is provided, this will be calculated automatically
   */
  pageCount?: number;

  /**
   * Total count of items (for automatic pageCount calculation)
   * If provided, pageCount will be calculated as Math.ceil(totalCount / pageSize)
   */
  totalCount?: number;

  /**
   * Callback for pagination changes (for manual pagination)
   */
  onPaginationChange?: (
    updater:
      | { pageIndex: number; pageSize: number }
      | ((old: { pageIndex: number; pageSize: number }) => {
          pageIndex: number;
          pageSize: number;
        })
  ) => void;

  /**
   * Controlled pagination state (for manual pagination)
   * If provided, the table will use this instead of internal state
   */
  pagination?: { pageIndex: number; pageSize: number };

  /**
   * Invalidate the query when the page is changed
   */
  onInvalidate?: () => void;

  /**
   * Enable manual filtering (server-side)
   * @default false
   */
  manualFiltering?: boolean;

  /**
   * Enable manual sorting (server-side)
   * @default false
   */
  manualSorting?: boolean;

  /**
   * Controlled sorting state (for server-side sorting)
   * If provided, the table will use this instead of internal state
   */
  sorting?: SortingState;

  /**
   * Callback for sorting changes (for server-side sorting)
   */
  onSortingChange?: OnChangeFn<SortingState>;

  /**
   * Render custom filters
   * @default undefined
   */
  renderCustomFilters?: () => React.ReactNode;
};

export function DataTable<TData, TValue>({
  data,
  columns,
  urlState,
  searchPlaceholder,
  searchKey,
  filters = [],
  globalFilterFn,
  enableFullHeight = true,
  minHeight,
  bottomOffset = 80,
  defaultPageSize = 20,
  className,
  tableClassName,
  bulkActions,
  showViewOptions,
  loading = false,
  skeletonRows = 20,
  manualPagination = true,
  manualFiltering = true,
  manualSorting = false,
  sorting: externalSorting,
  onSortingChange: externalOnSortingChange,
  pageCount,
  totalCount,
  pagination: externalPagination,
  onPaginationChange,
  onInvalidate,
  renderCustomFilters,
}: DataTableProps<TData, TValue>) {
  const appliedSearchPlaceholder = searchPlaceholder ?? 'Filter...';
  const [rowSelection, setRowSelection] = useState({});
  const [localSorting, setLocalSorting] = useState<SortingState>([]);

  const sorting = urlState?.sorting ?? externalSorting ?? localSorting;
  const handleSortingChange: OnChangeFn<SortingState> =
    externalOnSortingChange ?? urlState?.onSortingChange ?? setLocalSorting;

  const [columnVisibility, setColumnVisibility, SaveColumnVisibilityStatusFeatureImpl] =
    useColumnVisibility();
  const [globalFilter, setGlobalFilter] = useState('');
  const [columnFilters, setColumnFilters] = useState<{ id: string; value: unknown }[]>([]);
  const [columnSizing, setColumnSizing] = useState<ColumnSizingState>({});
  const [localPagination, setLocalPagination] = useState({
    pageIndex: 0,
    pageSize: defaultPageSize,
  });

  // Use external pagination if provided (for manual pagination), otherwise use local state
  const pagination = urlState?.pagination ?? externalPagination ?? localPagination;

  // Wrap pagination change to clear row selection
  const handlePaginationChange = (
    updater:
      | { pageIndex: number; pageSize: number }
      | ((old: { pageIndex: number; pageSize: number }) => { pageIndex: number; pageSize: number })
  ) => {
    setRowSelection({}); // Clear selection on pagination change
    const handler = urlState?.onPaginationChange ?? onPaginationChange ?? setLocalPagination;
    handler(updater);
  };

  const rawPageCount = totalCount
    ? Math.ceil(totalCount / (pagination.pageSize || defaultPageSize))
    : pageCount;

  const calculatedPageCount = rawPageCount || 1;
  //TODO: Fix me later
  // Calculate table height for scrolling
  const { height, containerRef } = useFullHeightTable({
    minHeight,
    bottomOffset,
    autoDetectHeaders: true,
    autoDetectElementsAbove: true,
  });

  const table = useReactTable({
    data,
    columns,
    state: {
      sorting,
      columnVisibility,
      rowSelection,
      columnFilters: urlState?.columnFilters ?? columnFilters,
      globalFilter: urlState?.globalFilter ?? globalFilter,
      pagination: urlState?.pagination ?? pagination,
      columnSizing,
    },
    enableRowSelection: true,
    onRowSelectionChange: setRowSelection,
    onSortingChange: handleSortingChange,
    onColumnVisibilityChange: setColumnVisibility,
    onColumnSizingChange: setColumnSizing,
    columnResizeMode: 'onChange',
    enableColumnResizing: true,
    globalFilterFn,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    ...(!manualSorting && { getSortedRowModel: getSortedRowModel() }),
    getFacetedRowModel: getFacetedRowModel(),
    getFacetedUniqueValues: getFacetedUniqueValues(),
    onPaginationChange: handlePaginationChange,
    onGlobalFilterChange: urlState?.onGlobalFilterChange ?? setGlobalFilter,
    onColumnFiltersChange: urlState?.onColumnFiltersChange ?? setColumnFilters,
    manualPagination,
    pageCount: calculatedPageCount,
    manualFiltering,
    manualSorting,
    _features: [SaveColumnVisibilityStatusFeatureImpl],
  });

  return (
    <div
      ref={containerRef}
      className={cn(
        'max-sm:has-[div[role="toolbar"]]:mb-16',
        'flex flex-1 flex-col gap-4',
        className
      )}
    >
      <DataTableToolbar
        table={table}
        searchPlaceholder={appliedSearchPlaceholder}
        searchKey={searchKey}
        filters={filters}
        showViewOptions={showViewOptions}
        renderCustomFilters={renderCustomFilters}
      />
      <div
        className={cn('overflow-auto rounded-md border', tableClassName)}
        style={enableFullHeight ? { maxHeight: height, minHeight: `${minHeight}px` } : undefined}
      >
        <Table
          className="table-fixed"
          //  style={{ width: table.getCenterTotalSize() }} // TODO: Check me later
        >
          <DataTableHeader table={table} />
          <DataTableBody table={table} loading={loading} skeletonRows={skeletonRows} />
        </Table>
      </div>
      <DataTablePagination table={table} onInvalidate={onInvalidate} />
      {bulkActions?.(table)}
    </div>
  );
}

import { CheckIcon, PlusCircledIcon } from '@radix-ui/react-icons';
import type { Column } from '@tanstack/react-table';
import type * as React from 'react';
import { Badge } from '../../ui/display/badge';
import { Button } from '../../ui/actions/button';
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from '../../ui/forms/command';
import { Popover, PopoverContent, PopoverTrigger } from '../../ui/overlays/popover';
import { Separator } from '../../ui/display/separator';
import { cn } from '../../../lib/utils';
import { compareSearching } from '../../../utils';

type DataTableFacetedFilterProps<TData, TValue> = {
  column?: Column<TData, TValue>;
  title?: string;
  noResultPlaceholder?: string;
  clearFilterPlaceholder?: string;
  selectedCountPlaceholder?: React.ReactNode;
  options: {
    label: string;
    value: string;
    icon?: React.ComponentType<{ className?: string }>;
  }[];
};

const DEFAULT_SELECTED_COUNT_PLACEHOLDER = 'Selected {count} items';

export function DataTableFacetedFilter<TData, TValue>({
  column,
  title,
  noResultPlaceholder = 'No results found.',
  clearFilterPlaceholder = 'Clear filters',
  selectedCountPlaceholder = DEFAULT_SELECTED_COUNT_PLACEHOLDER,
  options,
}: DataTableFacetedFilterProps<TData, TValue>) {
  const facets = column?.getFacetedUniqueValues();
  const selectedValues = new Set(column?.getFilterValue() as string[]);

  const isDifferentFromDefaultSelectedCountPlaceholder =
    typeof selectedCountPlaceholder === 'string'
      ? selectedCountPlaceholder !== DEFAULT_SELECTED_COUNT_PLACEHOLDER
      : true;

  const renderSelectedCount = () => {
    if (isDifferentFromDefaultSelectedCountPlaceholder) {
      return selectedCountPlaceholder;
    }

    if (typeof selectedCountPlaceholder === 'string') {
      return selectedCountPlaceholder.replace('{count}', selectedValues.size.toString());
    }

    return selectedCountPlaceholder;
  };

  return (
    <Popover>
      <PopoverTrigger
        render={(props) => (
          <Button {...props} variant="outline" size="sm" className="h-8 border-dashed">
            <PlusCircledIcon className="size-4" />
            {title}
            {selectedValues?.size > 0 && (
              <>
                <Separator orientation="vertical" className="mx-2 h-4" />
                <Badge variant="info" className="rounded-sm px-1 font-normal lg:hidden">
                  {selectedValues.size}
                </Badge>
                <div className="hidden space-x-1 lg:flex">
                  {selectedValues.size > 2 ? (
                    <Badge variant="info" className="rounded-sm px-1 font-normal">
                      {renderSelectedCount()}
                    </Badge>
                  ) : (
                    options
                      .filter((option) => selectedValues.has(option.value))
                      .map((option) => (
                        <Badge
                          variant="info"
                          key={option.value}
                          className="rounded-sm px-1 font-normal"
                        >
                          {option.label}
                        </Badge>
                      ))
                  )}
                </div>
              </>
            )}
          </Button>
        )}
      />
      <PopoverContent className="w-[200px] p-0" align="start">
        <Command filter={compareSearching}>
          <CommandInput placeholder={title} />
          <CommandList>
            <CommandEmpty>{noResultPlaceholder}</CommandEmpty>
            <CommandGroup>
              {options.map((option) => {
                const isSelected = selectedValues.has(option.value);
                return (
                  <CommandItem
                    withoutCheckIcon
                    key={option.value}
                    onSelect={() => {
                      if (isSelected) {
                        selectedValues.delete(option.value);
                      } else {
                        selectedValues.add(option.value);
                      }
                      const filterValues = Array.from(selectedValues);
                      column?.setFilterValue(filterValues.length ? filterValues : undefined);
                    }}
                  >
                    <div
                      className={cn(
                        'flex size-4 items-center justify-center rounded-sm border border-primary',
                        isSelected
                          ? 'bg-primary text-primary-foreground'
                          : 'opacity-50 [&_svg]:invisible'
                      )}
                    >
                      <CheckIcon className={cn('h-4 w-4 text-background')} />
                    </div>
                    {option.icon && <option.icon className="size-4 text-muted-foreground" />}
                    <span>{option.label}</span>
                    {facets?.get(option.value) && (
                      <span className="ms-auto flex h-4 w-4 items-center justify-center text-right font-mono text-xs">
                        {facets.get(option.value)}
                      </span>
                    )}
                  </CommandItem>
                );
              })}
            </CommandGroup>
            {selectedValues.size > 0 && (
              <>
                <CommandSeparator />
                <CommandGroup>
                  <CommandItem
                    onSelect={() => column?.setFilterValue(undefined)}
                    className="justify-center text-center"
                  >
                    {clearFilterPlaceholder}
                  </CommandItem>
                </CommandGroup>
              </>
            )}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

import { CheckIcon, MagnifyingGlassIcon, PlusCircledIcon } from '@radix-ui/react-icons';
import { useEffect, useMemo, useRef, useState } from 'react';
import type * as React from 'react';
import { Badge } from '../../../ui/display/badge';
import { Button } from '../../../ui/actions/button';
import { Input } from '../../../ui/forms/input';
import { Popover, PopoverContent, PopoverTrigger } from '../../../ui/overlays/popover';
import { Separator } from '../../../ui/display/separator';
import { Skeleton } from '../../../ui/feedback/skeleton';
import { VirtualizedContainer as VirtualizedList } from '../../../patterns/virtualized-list';
import { cn } from '../../../../lib/utils';
import { useControlledState } from '../../../../hooks/use-controlled-state';

type DataTableFacetedFilterLabels = {
  selectedCount: (count: number) => string;
  clear: string;
};

type DataTableFacetedFilterProps = {
  label?: string;
  options: {
    label: string;
    value: string;
    icon?: React.ComponentType<{ className?: string }>;
  }[];
  onChange?: (value: string[]) => void;
  value: string[];
  labels?: Partial<DataTableFacetedFilterLabels>;
};

const defaultFacetedFilterLabels: DataTableFacetedFilterLabels = {
  selectedCount: (count) => `${count} selected`,
  clear: 'Clear filters',
};

export const FormDataTableFacetedFilter = ({
  label,
  options,
  onChange: onChangeProp,
  value: valueProp,
  labels,
}: DataTableFacetedFilterProps) => {
  const mergedLabels = { ...defaultFacetedFilterLabels, ...labels };

  const [valueState, setValue] = useControlledState({
    defaultValue: [],
    value: valueProp,
    onChange: onChangeProp,
  });

  const value = valueState ?? [];

  const [open, setOpen] = useState(false);
  const [searchValue, setSearchValue] = useState('');
  const [debouncedSearchValue, setDebouncedSearchValue] = useState('');
  const [debouncedInputLoading, setDebouncedInputLoading] = useState(false);
  const debounceTimerRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  useEffect(() => {
    return () => {
      if (debounceTimerRef.current !== undefined) {
        clearTimeout(debounceTimerRef.current);
        debounceTimerRef.current = undefined;
      }
    };
  }, []);

  // Custom filtering logic
  const filteredOptions = useMemo(() => {
    if (!debouncedSearchValue) return options;
    return options.filter(
      (option) =>
        option.label.toLowerCase().includes(debouncedSearchValue.toLowerCase()) ||
        option.value.toLowerCase().includes(debouncedSearchValue.toLowerCase())
    );
  }, [options, debouncedSearchValue]);

  const handleSelect = (selectedValue: string) => {
    const newValue = value.includes(selectedValue)
      ? value.filter((v) => v !== selectedValue)
      : [...value, selectedValue];
    setValue(newValue);
  };

  const handleClear = () => {
    setValue([]);
  };

  const handleOpenChange = (newOpen: boolean) => {
    setOpen(newOpen);
    if (!newOpen) {
      // Clear search values when popover closes
      setSearchValue('');
      setDebouncedSearchValue('');
      setDebouncedInputLoading(false);
      if (debounceTimerRef.current) {
        clearTimeout(debounceTimerRef.current);
      }
    }
  };

  return (
    <Popover open={open} onOpenChange={handleOpenChange}>
      <PopoverTrigger
        render={(props) => (
          <Button {...props} variant="outline" size="sm" className="h-8 border-dashed">
            <PlusCircledIcon className="size-4" />
            {label}
            {value.length > 0 && (
              <>
                <Separator orientation="vertical" className="mx-2 h-4" />
                <Badge variant="info" className="rounded-sm px-1 font-normal lg:hidden">
                  {value.length}
                </Badge>
                <div className="hidden space-x-1 lg:flex">
                  {value.length > 2 ? (
                    <Badge variant="info" className="rounded-sm px-1 font-normal">
                      {mergedLabels.selectedCount(value.length)}
                    </Badge>
                  ) : (
                    options
                      .filter((option) => value.includes(option.value))
                      .map((option) => (
                        <Badge
                          variant="info"
                          key={option.value}
                          className="rounded-sm px-1 font-normal"
                        >
                          <span className="max-w-[150px] truncate">{option.label}</span>
                        </Badge>
                      ))
                  )}
                </div>
              </>
            )}
          </Button>
        )}
      />
      <PopoverContent className="w-[200px] p-0" align="start">
        <div className="flex flex-col">
          <div className="border-b p-2">
            <Input
              placeholder={label}
              value={searchValue}
              onChange={(e) => {
                const newValue = e.target.value;
                setSearchValue(newValue);

                if (debounceTimerRef.current) {
                  clearTimeout(debounceTimerRef.current);
                }

                // Update immediately if empty, otherwise debounce
                if (newValue === '') {
                  setDebouncedSearchValue('');
                  setDebouncedInputLoading(false);
                } else {
                  setDebouncedInputLoading(true);
                  debounceTimerRef.current = setTimeout(() => {
                    setDebouncedSearchValue(newValue);
                    setDebouncedInputLoading(false);
                  }, 300);
                }
              }}
              prefixIcon={<MagnifyingGlassIcon className="size-4" />}
              className="h-8"
            />
          </div>
          {/* Important: debouncedInputLoading to reinitialize the virtualized list after search */}
          {debouncedInputLoading ? (
            <div className="space-y-1 p-2">
              {Array.from({ length: 5 }).map((_, index) => (
                <div
                  key={index}
                  className="flex cursor-default select-none items-center rounded-sm px-2 py-1.5"
                >
                  <Skeleton className="size-4 rounded-sm" />
                  <Skeleton className="ml-2 h-4 w-24" />
                </div>
              ))}
            </div>
          ) : (
            <div role="listbox" aria-multiselectable="true">
              <VirtualizedList
                data={filteredOptions}
                renderItem={(item, _index, _virtualItem) => {
                  const isSelected = value.includes(item.value);
                  return (
                    <div
                      className="flex cursor-default select-none items-center rounded-sm px-2 py-1.5 text-sm outline-none hover:bg-accent hover:text-accent-foreground data-disabled:pointer-events-none data-disabled:opacity-50"
                      onClick={() => handleSelect(item.value)}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter' || e.key === ' ') {
                          e.preventDefault();
                          handleSelect(item.value);
                        }
                      }}
                      role="option"
                      aria-selected={isSelected}
                      tabIndex={0}
                    >
                      <div
                        className={cn(
                          'flex size-4 items-center justify-center rounded-sm border border-primary',
                          isSelected
                            ? 'bg-primary text-primary-foreground'
                            : 'opacity-50 [&_svg]:invisible'
                        )}
                      >
                        <CheckIcon className={cn('h-4 w-4 text-background')} />
                      </div>
                      {item.icon && <item.icon className="ml-2 size-4 text-muted-foreground" />}
                      <span className="ml-2">{item.label}</span>
                    </div>
                  );
                }}
              />
            </div>
          )}
          {value.length > 0 && (
            <>
              <Separator />
              <div className="p-1">
                <button
                  type="button"
                  onClick={handleClear}
                  className="flex w-full cursor-default select-none items-center justify-center rounded-sm px-2 py-1.5 text-center text-sm outline-none hover:bg-accent hover:text-accent-foreground"
                >
                  {mergedLabels.clear}
                </button>
              </div>
            </>
          )}
        </div>
      </PopoverContent>
    </Popover>
  );
};

