              const sticky = cell.column.columnDef.meta?.sticky;
              return (
                <TableCell
                  key={cell.id}
                  className={cn(
                    'truncate',
                    sticky && 'sticky bg-background',
                    sticky === 'left' &&
                      'left-0 after:absolute after:top-0 after:right-0 after:bottom-0 after:w-px after:shadow-[2px_0_5px_0_rgba(0,0,0,0.1)]',
