  toggleColumns: string;
  cancel: string;
  saveChanges: string;
};

type DataTableViewOptionsProps<TData> = {
  table: Table<TData>;
  labels?: Partial<DataTableViewOptionsLabels>;
};

const defaultViewOptionsLabels: DataTableViewOptionsLabels = {
  trigger: 'View',
  toggleColumns: 'Toggle columns',
  cancel: 'Cancel',
  saveChanges: 'Save changes',
};

export function DataTableViewOptions<TData>({ table, labels }: DataTableViewOptionsProps<TData>) {
  const mergedLabels = { ...defaultViewOptionsLabels, ...labels };
  const [isOpen, setIsOpen] = useState(false);
  const [pendingVisibility, setPendingVisibility] = useState<VisibilityState>({});

  const handleOpenChange = useCallback(
    (open: boolean) => {
      if (open) {
        // Store current visibility state when opening
        const currentVisibility: VisibilityState = {};
        for (const column of table.getAllColumns()) {
          if (typeof column.accessorFn !== 'undefined' && column.getCanHide()) {
            currentVisibility[column.id] = column.getIsVisible();
          }
        }
        setPendingVisibility(currentVisibility);
      }
      setIsOpen(open);
    },
    [table]
  );

  const handleCheckedChange = useCallback((columnId: string, value: boolean) => {
    setPendingVisibility((prev) => {
      const updated = {
        ...prev,
        [columnId]: value,
      };
      return updated;
    });
  }, []);

  const handleConfirm = useCallback(() => {
    table.setColumnVisibility(pendingVisibility);
    setIsOpen(false);
  }, [table, pendingVisibility]);

  const handleClose = useCallback(() => {
    setIsOpen(false);
  }, []);

  const columns = table
    .getAllColumns()
    .filter((column) => typeof column.accessorFn !== 'undefined' && column.getCanHide());

  return (
    <DropdownMenu modal={false} open={isOpen} onOpenChange={handleOpenChange}>
      <DropdownMenuTrigger
        render={(props) => (
          <Button {...props} variant="outline" size="sm" className="ms-auto hidden h-8 lg:flex">
            <MixerHorizontalIcon className="size-4" />
            {mergedLabels.trigger}
          </Button>
        )}
      />
      <DropdownMenuContent align="end" className="w-[220px]">
        <DropdownMenuLabel className="flex items-center gap-2">
          {mergedLabels.toggleColumns}
          <Button
            variant={table.getEnabledSaveColumnVisibilityStatus() ? 'success' : 'default'}
            appearance={table.getEnabledSaveColumnVisibilityStatus() ? 'light' : 'ghost'}
            size="sm"
            className="ms-auto hidden h-8 lg:flex"
            onClick={() =>
              table.setEnabledSaveColumnVisibilityStatus(
                !table.getEnabledSaveColumnVisibilityStatus()
              )
            }
          >
            <BookmarkIcon className="h-4 w-4" />
          </Button>
        </DropdownMenuLabel>
        <DropdownMenuSeparator />
        {columns
          .filter((column) => Boolean(column?.id))
          .map((column) => {
            const columnId = column.id as string; // Type assertion safe after filter
            const headerLabel = column.columnDef?.meta?.headerLabel || columnId;
            return (
              <DropdownMenuCheckboxItem
                key={columnId}
                className="capitalize"
                checked={pendingVisibility[columnId] ?? column.getIsVisible()}
                onCheckedChange={(value: boolean) => handleCheckedChange(columnId, value)}
                onSelect={(e) => e.preventDefault()}
              >
                {headerLabel}
              </DropdownMenuCheckboxItem>
            );
          })}
        <DropdownMenuSeparator />
        <div className="flex gap-2 p-2">
          <Button variant="outline" size="sm" className="flex-1" onClick={handleClose}>
            {mergedLabels.cancel}
          </Button>
          <Button size="sm" className="flex-1" onClick={handleConfirm}>
            {mergedLabels.saveChanges}
          </Button>
        </div>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import type { RowData, Table, TableFeature, VisibilityState } from '@tanstack/react-table';
import { useState } from 'react';

const STORAGE_KEY_PREFIX = 'table-view-options';

function getCurrentPathname(): string {
  if (globalThis.window !== undefined && globalThis.window?.location?.pathname) {
    return globalThis.window.location.pathname;
  }

  return 'default';
}

function getStorageKey(pathname: string): string {
  return `${STORAGE_KEY_PREFIX}:${pathname}`;
}

function getStoredVisibility(pathname: string): VisibilityState | null {
  try {
    const storageKey = getStorageKey(pathname);
    const savedValue = localStorage.getItem(storageKey);
    if (savedValue) {
      return JSON.parse(savedValue) as VisibilityState;
    }
    return null;
  } catch {
    // localStorage might be disabled or data corrupted
    return null;
  }
}

function saveStoredVisibility(pathname: string, visibility: VisibilityState): void {
  try {
    const storageKey = getStorageKey(pathname);
    localStorage.setItem(storageKey, JSON.stringify(visibility));
  } catch {
    // Storage might be full or disabled
  }
}

function clearStoredVisibility(pathname: string): void {
  try {
    const storageKey = getStorageKey(pathname);
    localStorage.removeItem(storageKey);
  } catch {
    // Storage might be disabled
  }
}

type UseColumnVisibilityReturn = [
  VisibilityState,
  (visibility: VisibilityState | ((prev: VisibilityState) => VisibilityState)) => void,
  TableFeature<RowData>,
];

export function useColumnVisibility(storageKey?: string): UseColumnVisibilityReturn {
  const currentPathname = storageKey ?? getCurrentPathname();

  const [columnVisibility, setColumnVisibilityState] = useState<VisibilityState>(() => {
    const storedVisibility = getStoredVisibility(currentPathname);
    return storedVisibility ?? {};
  });

  const [enabledSaveColumnStatus, setEnabledSaveColumnStatus] = useState(
    Boolean(Object.keys(columnVisibility).length > 0)
  );

  const setColumnVisibility = (
    visibility: VisibilityState | ((prev: VisibilityState) => VisibilityState)
  ): void => {
    setColumnVisibilityState((prev) => {
      const next = typeof visibility === 'function' ? visibility(prev) : visibility;
      if (enabledSaveColumnStatus) {
        saveStoredVisibility(currentPathname, next);
      } else {
        clearStoredVisibility(currentPathname);
      }
      return next;
    });
  };

  const SaveColumnVisibilityStatusFeatureImpl: TableFeature<RowData> = {
    // biome-ignore lint/suspicious/noExplicitAny: <explanation>
    getInitialState: (state: any) => {
      return {
        ...state,
        saveColumnVisibilityStatus: Boolean(Object.keys(columnVisibility).length > 0),
      };
    },

    createTable: <TData extends RowData>(table: Table<TData>): void => {
      table.getEnabledSaveColumnVisibilityStatus = () => {
        return table.getState().saveColumnVisibilityStatus ?? false;
      };

      table.setEnabledSaveColumnVisibilityStatus = (status: boolean) => {
        setEnabledSaveColumnStatus(status);
        table.setState((old) => ({
          ...old,
          saveColumnVisibilityStatus: status,
        }));
      };
    },
  };

  return [columnVisibility, setColumnVisibility, SaveColumnVisibilityStatusFeatureImpl];
}

import * as React from 'react';
import { format } from 'date-fns';
import { Calendar as CalendarIcon } from 'lucide-react';
import { CalendarV2 } from '../../ui/forms/calendar/calendar-v2';
import type { CalendarV2Props } from '../../ui/forms/calendar/calendar-v2';
import { Popover, PopoverContent, PopoverTrigger } from '../../ui/overlays/popover';
import { Button } from '../../ui/actions/button';
import { useControlledState } from '../../../hooks/use-controlled-state';
import { cn } from '../../../lib/utils';
import type { DateValue } from '../date-picker/types';

// ─────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────

export type DatePickerV2Props = Omit<
  CalendarV2Props<'single'>,
  'type' | 'value' | 'onChange' | 'className' | 'style'
> & {
  value?: DateValue;
  defaultValue?: DateValue;
  onChange?: (value: DateValue) => void;
  /** Placeholder shown when no date is selected. */
  placeholder?: string;
  /**
   * When true, a staged value is kept while the popover is open and only
   * committed via the Apply button. When false, changes propagate immediately
   * and the popover closes after selection.
   */
  hasApplyButton?: boolean;
  /** Applied to the trigger button. */
  className?: string;
  'aria-invalid'?: boolean;
};

// ─────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────

function toDate(value: DateValue): Date | undefined {
  if (!value) return undefined;
  if (value instanceof Date) return isNaN(value.getTime()) ? undefined : value;
  const d = new Date(value);
  return isNaN(d.getTime()) ? undefined : d;
}

function formatSingleDate(value: DateValue, placeholder: string): string {
  const date = toDate(value);
  return date ? format(date, 'MMM d, yyyy') : placeholder;
}

// ─────────────────────────────────────────────────────────────
// Component
// ─────────────────────────────────────────────────────────────

export function DatePickerV2({
  value: valueProp,
  defaultValue,
  onChange: onChangeProp,
  placeholder = 'Select date',
  hasApplyButton = false,
  className,
  'aria-invalid': ariaInvalid,
  disabled,
  renderActions: renderActionsProp,
  ...calendarProps
}: DatePickerV2Props) {
  const [value, setValue] = useControlledState<DateValue>({
    value: valueProp,
    defaultValue,
    onChange: onChangeProp,
  });

  const [isOpen, setIsOpen] = React.useState(false);
  // Staged value — only diverges from `value` while the popover is open with hasApplyButton.
  const [tempValue, setTempValue] = React.useState<DateValue>(value);

  const handleOpenChange = (nextOpen: boolean) => {
    if (nextOpen) {
      setTempValue(value); // sync staged state on open
      setIsOpen(true);
    } else if (hasApplyButton) {
      setTempValue(value); // discard staged changes on dismiss
      setIsOpen(false);
    } else {
      setIsOpen(false);
    }
  };

  const handleCalendarChange = (newValue: DateValue) => {
    if (hasApplyButton) {
      setTempValue(newValue);
    } else {
      setValue(newValue);
      setIsOpen(false);
    }
  };

  const handleApply = () => {
    setValue(tempValue);
    setIsOpen(false);
  };

  const handleCancel = () => {
    setTempValue(value);
    setIsOpen(false);
  };

  const activeValue = hasApplyButton ? tempValue : value;
  const isEmpty = !activeValue;
  const displayText = formatSingleDate(activeValue, placeholder);

  return (
    <Popover open={isOpen} onOpenChange={handleOpenChange}>
      <PopoverTrigger
        disabled={disabled}
        render={(props) => (
          <Button
            {...props}
            type="button"
            variant="outline"
            data-empty={isEmpty}
            aria-invalid={ariaInvalid}
            disabled={disabled}
            className={cn(
              'w-full justify-start text-start font-normal',
              'aria-invalid:border-destructive aria-invalid:ring-destructive/20',
              'data-[empty=true]:text-muted-foreground',
              'dark:aria-invalid:ring-destructive/40',
              className
            )}
          >
            {displayText}
            <CalendarIcon className="ms-auto h-4 w-4 opacity-50" />
          </Button>
        )}
      />
      <PopoverContent className="w-auto overflow-hidden border p-0 ring-0" align="start">
        <CalendarV2
          type="single"
          value={activeValue}
          onChange={handleCalendarChange}
          disabled={disabled}
          className="rounded-[inherit] border-0 shadow-none"
          renderActions={
            hasApplyButton
              ? () => (
                  <div className="flex justify-end gap-2">
                    <Button variant="ghost" size="sm" type="button" onClick={handleCancel}>
                      Cancel
                    </Button>
                    <Button size="sm" type="button" onClick={handleApply}>
                      Apply
                    </Button>
                  </div>
                )
              : renderActionsProp
          }
          {...calendarProps}
        />
      </PopoverContent>
    </Popover>
  );
}

