                key={preset.name}
                type="button"
                variant="ghost"
                size="sm"
                className="h-8 justify-start text-xs"
                disabled={disabled}
                onClick={() => handlePresetClick(preset)}
              >
                {preset.label}
              </Button>
            ))}
          </div>
        )}
      </div>
    </PopoverContent>
  );
}

