function MonthRangeCal({
  selectedMonthRange,
  onMonthRangeSelect,
  onStartMonthSelect,
  callbacks,
  variant,
  minDate,
  maxDate,
  quickSelectors = QUICK_SELECTORS,
  showQuickSelectors = true,
  onYearBackward,
  onYearForward,
}: MonthRangeCalProps) {
  const [startYear, setStartYear] = React.useState<number>(
    selectedMonthRange?.start.getFullYear() ?? new Date().getFullYear()
  );
  const [startMonth, setStartMonth] = React.useState<number>(
    selectedMonthRange?.start?.getMonth() ?? new Date().getMonth()
  );
  const [endYear, setEndYear] = React.useState<number>(
    selectedMonthRange?.end?.getFullYear() ?? new Date().getFullYear() + 1
  );
  const [endMonth, setEndMonth] = React.useState<number>(
    selectedMonthRange?.end?.getMonth() ?? new Date().getMonth()
  );
  const [rangePending, setRangePending] = React.useState<boolean>(false);
  const [endLocked, setEndLocked] = React.useState<boolean>(true);
  const [menuYear, setMenuYear] = React.useState<number>(startYear);

  if (minDate && maxDate && minDate > maxDate) minDate = maxDate;

  const currentYear = new Date().getFullYear();
  const yearOptions = generateYears(currentYear, 20);

  return (
    <div className="flex gap-4">
      <div className="min-w-[400px] space-y-4">
        <div className="relative flex items-center justify-evenly pt-1 pb-2">
          <Select
            value={menuYear.toString()}
            onValueChange={(value) => {
              if (value) {
                const newYear = Number.parseInt(value, 10);
                setMenuYear(newYear);
              }
            }}
          >
            <SelectTrigger className="h-7 w-[100px] text-sm">
              <SelectValue>
                {callbacks?.yearLabel ? callbacks.yearLabel(menuYear) : menuYear}
              </SelectValue>
            </SelectTrigger>
            <SelectContent>
              {yearOptions.map((year) => (
                <SelectItem key={year} value={year.toString()}>
                  {callbacks?.yearLabel ? callbacks.yearLabel(year) : year}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <button
            type="button"
            onClick={() => {
              setMenuYear(menuYear - 1);
              if (onYearBackward) onYearBackward();
            }}
            className={cn(
              buttonVariants({ variant: variant?.chevrons ?? 'outline' }),
              'absolute left-1 inline-flex h-7 w-7 items-center justify-center p-0'
            )}
          >
            <ChevronLeft className="h-4 w-4 opacity-50" />
          </button>
          <button
            type="button"
            onClick={() => {
              setMenuYear(menuYear + 1);
              if (onYearForward) onYearForward();
            }}
            className={cn(
              buttonVariants({ variant: variant?.chevrons ?? 'outline' }),
              'absolute right-1 inline-flex h-7 w-7 items-center justify-center p-0'
            )}
          >
            <ChevronRight className="h-4 w-4 opacity-50" />
          </button>
          <Select
            value={(menuYear + 1).toString()}
            onValueChange={(value) => {
              if (value) {
                const newYear = Number.parseInt(value, 10);
                setMenuYear(newYear - 1);
              }
            }}
          >
            <SelectTrigger className="h-7 w-[100px] text-sm">
              <SelectValue>
                {callbacks?.yearLabel ? callbacks.yearLabel(menuYear + 1) : menuYear + 1}
              </SelectValue>
            </SelectTrigger>
            <SelectContent>
              {yearOptions.map((year) => (
                <SelectItem key={year} value={year.toString()}>
                  {callbacks?.yearLabel ? callbacks.yearLabel(year) : year}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <table className="w-full border-collapse space-y-1">
          <tbody>
            {MONTHS.map((monthRow, a) => {
              return (
                <tr key={`row-${a}`} className="mt-2 flex w-full">
                  {monthRow.map((m, i) => {
                    return (
                      <td
                        key={`${m.number}-${m.yearOffset}`}
                        className={cn(
                          cn(
                            cn(
                              cn(
                                'relative h-10 w-1/4 p-0 text-center text-sm focus-within:relative focus-within:z-20 [&:has([aria-selected])]:bg-accent first:[&:has([aria-selected])]:rounded-l-md last:[&:has([aria-selected])]:rounded-r-md [&:has([aria-selected].day-outside)]:bg-accent/50 [&:has([aria-selected].day-range-end)]:rounded-r-md',
                                (menuYear + m.yearOffset > startYear ||
                                  (menuYear + m.yearOffset === startYear &&
                                    m.number > startMonth)) &&
                                  (menuYear + m.yearOffset < endYear ||
                                    (menuYear + m.yearOffset === endYear && m.number < endMonth)) &&
                                  (rangePending || endLocked)
                                  ? 'bg-accent text-accent-foreground'
                                  : ''
                              ),
                              menuYear + m.yearOffset === startYear &&
                                m.number === startMonth &&
                                (rangePending || endLocked)
                                ? 'rounded-l-md bg-accent text-accent-foreground'
                                : ''
                            ),
                            menuYear + m.yearOffset === endYear &&
                              m.number === endMonth &&
                              (rangePending || endLocked) &&
                              menuYear + m.yearOffset >= startYear &&
                              m.number >= startMonth
                              ? 'rounded-r-md bg-accent text-accent-foreground'
                              : ''
                          ),
                          i === 3 ? 'mr-2' : i === 4 ? 'ml-2' : ''
                        )}
                        onMouseEnter={() => {
                          if (rangePending && !endLocked) {
                            setEndYear(menuYear + m.yearOffset);
                            setEndMonth(m.number);
                          }
                        }}
                      >
                        <button
                          type="button"
                          onClick={() => {
                            if (rangePending) {
                              if (
                                menuYear + m.yearOffset < startYear ||
                                (menuYear + m.yearOffset === startYear && m.number < startMonth)
                              ) {
                                setRangePending(true);
                                setEndLocked(false);
                                setStartMonth(m.number);
                                setStartYear(menuYear + m.yearOffset);
                                setEndYear(menuYear + m.yearOffset);
                                setEndMonth(m.number);
                                if (onStartMonthSelect)
                                  onStartMonthSelect(new Date(menuYear + m.yearOffset, m.number));
                              } else {
                                setRangePending(false);
                                setEndLocked(true);
                                // Event fire data selected

                                if (onMonthRangeSelect)
                                  onMonthRangeSelect({
                                    start: new Date(startYear, startMonth),
                                    end: new Date(menuYear + m.yearOffset, m.number),
                                  });
                              }
                            } else {
                              setRangePending(true);
                              setEndLocked(false);
                              setStartMonth(m.number);
                              setStartYear(menuYear + m.yearOffset);
                              setEndYear(menuYear + m.yearOffset);
                              setEndMonth(m.number);
                              if (onStartMonthSelect)
                                onStartMonthSelect(new Date(menuYear + m.yearOffset, m.number));
                            }
                          }}
                          disabled={
                            (maxDate
                              ? menuYear + m.yearOffset > maxDate?.getFullYear() ||
                                (menuYear + m.yearOffset === maxDate?.getFullYear() &&
                                  m.number > maxDate.getMonth())
                              : false) ||
                            (minDate
                              ? menuYear + m.yearOffset < minDate?.getFullYear() ||
                                (menuYear + m.yearOffset === minDate?.getFullYear() &&
                                  m.number < minDate.getMonth())
                              : false)
                          }
                          className={cn(
                            buttonVariants({
                              variant:
                                (startMonth === m.number &&
                                  menuYear + m.yearOffset === startYear) ||
                                (endMonth === m.number &&
                                  menuYear + m.yearOffset === endYear &&
                                  !rangePending)
                                  ? (variant?.calendar?.selected ?? 'default')
                                  : (variant?.calendar?.main ?? 'ghost'),
                            }),
                            'h-full w-full p-0 font-normal aria-selected:opacity-100'
                          )}
                        >
                          {callbacks?.monthLabel ? callbacks.monthLabel(m) : m.name}
                        </button>
                      </td>
                    );
                  })}
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {showQuickSelectors ? (
        <div className="flex flex-col justify-center gap-1">
          {quickSelectors.map((s) => {
            return (
              <Button
                onClick={() => {
                  setStartYear(s.startMonth.getFullYear());
                  setStartMonth(s.startMonth.getMonth());
                  setEndYear(s.endMonth.getFullYear());
                  setEndMonth(s.endMonth.getMonth());
                  setRangePending(false);
                  setEndLocked(true);
                  if (onMonthRangeSelect)
                    onMonthRangeSelect({
                      start: s.startMonth,
                      end: s.endMonth,
                    });
                  if (s.onClick) s.onClick(s);
                }}
                key={s.label}
                variant={s.variant ?? 'outline'}
              >
                {s.label}
              </Button>
            );
          })}
        </div>
      ) : null}
    </div>
  );
}

