import { defaultFilterPanelLocaleV2, FilterPanelLocaleContextV2 } from './i18n';

const SaveTemplateDialog = lazy(() =>
  import('./components/save-template-dialog').then((mod) => ({ default: mod.SaveTemplateDialog }))
);
const DeleteTemplateDialog = lazy(() =>
  import('./components/delete-template-dialog').then((mod) => ({
    default: mod.DeleteTemplateDialog,
  }))
);
const RenameTemplateDialog = lazy(() =>
  import('./components/rename-template-dialog').then((mod) => ({
    default: mod.RenameTemplateDialog,
  }))
);

export function FilterPanelV2({
  filters,
  advancedFilters = [],
  advancedFilterGroups,
  values,
  defaultValues = {},
  onChange,
  onReset,
  advancedFiltersLabel = 'Advanced Filters',
  advancedFiltersButton,
  resetLabel,
  className,
  contentClassName,
  renderAfterFilters,
  primaryFiltersColumns,
  advancedFiltersColumns,
  disable,
  children,
  stickyOffsetTop = 'top-16',
  stickyBg = 'bg-white',
  stickyClassName = '-mx-4',
  isSticky = true,
  module,
  onApplyTemplate,
  onActiveTemplateChange,
  locale,
}: FilterPanelPropsV2) {
  const resolvedLocale = { ...defaultFilterPanelLocaleV2, ...locale };
  const [showAdvanced, setShowAdvanced] = useState(false);
  const advancedRef = useRef<HTMLDivElement>(null);
  const { sentinelRef, isStuck: rawIsStuck } = useStickyObserver();
  const isStuck = isSticky && rawIsStuck;

  // ── Template management ─────────────────────────────────────────────
  const templateManager = useTemplateManager({
    module,
    values,
    defaultValues,
    onApplyTemplate,
    onActiveTemplateChange,
    locale: resolvedLocale,
  });

  // Compute effective groups (prioritize advancedFilterGroups)
  const effectiveGroups: AdvancedFilterGroupV2[] = useMemo(() => {
    if (advancedFilterGroups && advancedFilterGroups.length > 0) {
      return advancedFilterGroups;
    }
    if (advancedFilters && advancedFilters.length > 0) {
      // Wrap flat list in single group with empty title
      return [{ title: '', filters: advancedFilters }];
    }
    return [];
  }, [advancedFilterGroups, advancedFilters]);

  // Flat list of all advanced filters for calculations
  const allAdvancedFilters = useMemo(
    () => effectiveGroups.flatMap((g) => g.filters),
    [effectiveGroups]
  );

  // Check if there are any advanced filters
  const hasAdvancedFilters = effectiveGroups.length > 0 && allAdvancedFilters.length > 0;
  // Count selected advanced filters that differ from default values
  const selectedAdvancedCount = useMemo(
    () =>
      countSelectedAdvancedFilters({
        allAdvancedFilters,
        values,
        defaultValues,
      }),
    [allAdvancedFilters, values, defaultValues]
  );

  const handleReset = () => {
    setShowAdvanced(false);
    onReset?.(templateManager.activeTemplate?.filters);
  };

  return (
    <FilterPanelLocaleContextV2.Provider value={resolvedLocale}>
      {isSticky && <div ref={sentinelRef} className="mb-0 h-0" />}
      <Card
        className={cn(
          isSticky && `sticky ${stickyOffsetTop} z-30`,
          'transition-[border-radius,margin] duration-200',
          isStuck && 'rounded-none',
          isStuck && stickyBg,
          isStuck && stickyClassName,
          className
        )}
      >
        <CardContent className="flex flex-col gap-4">
          {templateManager.enabled && (
            <div className="flex flex-col gap-1">
              <p className="font-medium text-muted-foreground text-sm">
                {resolvedLocale.savedTemplatesLabel}
              </p>
              <TemplateChip
                templates={templateManager.templates}
                activeTemplateId={templateManager.activeTemplateId}
                onSelect={templateManager.handleSelect}
                onSaveClick={templateManager.openSaveDialog}
                onUpdateClick={templateManager.handleUpdate}
                onDeleteRequest={templateManager.handleRequestDelete}
                onRenameRequest={templateManager.handleRequestRename}
                hasChangeFilter={templateManager.hasChangeFilter}
              />
            </div>
          )}
          {/* Main Filters */}
          <div className={cn('item-start flex justify-between', contentClassName)}>
            {/* Template chip — inline before filters */}
            <div
              className={cn(
                primaryFiltersColumns
                  ? getGridClasses(primaryFiltersColumns, 'flex flex-wrap items-center')
                  : 'flex flex-wrap items-center',
                'gap-4'
              )}
            >
              {filters.map((filter) => (
                <FilterField
                  key={filter.key}
                  filter={filter}
                  values={values}
                  onChange={onChange}
                  layout="row"
                />
              ))}

              {/* Custom content after main filters */}
              {renderAfterFilters}
            </div>
            {/* Template, Advanced Filters Toggle & Reset */}
            {(hasAdvancedFilters || onReset) && (
              <div className="flex items-start justify-end gap-2">
                {onReset && (
                  <Button
                    disabled={disable}
                    variant="ghost"
                    size="sm"
                    onClick={handleReset}
                    className="gap-2"
                  >
                    <RotateCcw className="h-4 w-4" />
                    {resetLabel}
                  </Button>
                )}
                {hasAdvancedFilters && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setShowAdvanced(!showAdvanced)}
                    className="relative gap-2"
                    data-advanced-filter-toggle
                  >
                    <Filter className="h-4 w-4" />
                    {advancedFiltersButton}
                    {selectedAdvancedCount > 0 && (
                      <Badge
                        variant="primary"
                        className="ml-1 h-5 min-w-5 rounded-full px-1.5 text-xs"
                      >
                        {selectedAdvancedCount}
                      </Badge>
                    )}
                  </Button>
                )}
              </div>
            )}
          </div>

          {/* Advanced Filters Content - Absolute Positioned with Animation */}
          {showAdvanced && hasAdvancedFilters && (
            <div
              ref={advancedRef}
              className="fade-in-0 slide-in-from-top-2 absolute top-full right-0 left-0 z-50 mt-2 animate-in rounded-lg border border-border bg-card shadow-lg duration-200"
            >
              {/* Header with Close Button */}
              <div className="flex items-center justify-between rounded-t-lg border-border border-b bg-muted/50 px-4 py-3">
                <h3 className="font-semibold text-sm">{advancedFiltersLabel}</h3>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setShowAdvanced(false)}
                  className="h-6 w-6 p-0 hover:bg-muted"
                >
                  <X className="h-4 w-4" />
                </Button>
              </div>

              {/* Groups */}
              <div className="space-y-6 p-4">
                {effectiveGroups.map((group, groupIndex) => (
                  <div key={group.title || `group-${groupIndex}`}>
                    {/* Group Title */}
                    {group.title && (
                      <h4 className="mb-3 font-bold text-primary text-sm">{group.title}</h4>
                    )}
                    {/* Group Filters Grid */}
                    <div
                      className={cn(
                        getGridClasses(advancedFiltersColumns, 'grid grid-cols-1 md:grid-cols-2'),
                        'gap-4'
                      )}
                    >
                      {group.filters.map((filter) => (
                        <FilterField
                          key={filter.key}
                          filter={filter}
                          values={values}
                          onChange={onChange}
                          layout="column"
                        />
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Additional content (e.g. always-visible required fields) */}
          {children}
        </CardContent>
      </Card>

      {/* ── Template dialogs ─────────────────────────────────────── */}
      {templateManager.enabled && (
        <>
          <SaveTemplateDialog
            open={templateManager.saveDialogOpen}
            onClose={templateManager.closeSaveDialog}
            onSave={templateManager.handleSave}
          />
          <DeleteTemplateDialog
            open={templateManager.deleteDialogOpen}
            templateName={templateManager.templateToDelete?.name ?? ''}
            onClose={templateManager.handleCancelDelete}
            onConfirm={templateManager.handleConfirmDelete}
          />
          <RenameTemplateDialog
            open={templateManager.renameDialogOpen}
            initialName={templateManager.templateToRename?.name ?? ''}
            onClose={templateManager.handleCancelRename}
            onRename={templateManager.handleConfirmRename}
          />
        </>
      )}
    </FilterPanelLocaleContextV2.Provider>
  );
}

import * as React from 'react';
import { createTypedDB, type EntityTable } from '../../../../lib/dexie';
import { useLiveQuery } from '../../../../lib/dexie';
import type { FilterValueV2 } from '../types';

// ─── Schema ─────────────────────────────────────────────────────────────────

export interface FilterTemplateDBV2 {
  id: string;
  module: string;
  name: string;
  filters: Record<string, FilterValueV2>;

  createdAt: number;
  updatedAt: number;
  /** `0` = not deleted, otherwise the timestamp of soft-deletion. Stored as number so IndexedDB can index it. */
  deletedAt: number;

  isSynced: boolean;
  serverId?: string;

  version: number;
}

type DB = {
  templates: EntityTable<FilterTemplateDBV2, 'id'>;
};

const CURRENT_DB_VERSION = 1;
const DELETED_AT_DEFAULT_VALUE = 0; // Using `0` instead of `null` for `deletedAt` allows us to leverage IndexedDB's numeric indexes for efficient range queries (e.g. find all non-deleted records with `deletedAt = 0`).

/**
 * Indexes:
 * - `id`                            — primary key
 * - `module`                        — list all templates for a module
 * - `[module+deletedAt+updatedAt]`  — **hot path**: fetch latest non-deleted template per module
 *                                     in a single indexed range-scan + `.last()`
 * - `[module+updatedAt]`            — general queries
 * - `isSynced`                      — find un-synced records for server sync
 * - `serverId`                      — look-up by remote id
 */
const filterTemplateDB = createTypedDB<DB>(
  'filter-templates',
  {
    templates: 'id, module, [module+deletedAt+updatedAt], [module+updatedAt], isSynced, serverId',
  },
  CURRENT_DB_VERSION
);

// ─── Hook ───────────────────────────────────────────────────────────────────

export interface UsePersistentFilterTemplateReturnV2 {
  /** The most-recently-updated non-deleted template for this module. */
  latestTemplate: FilterTemplateDBV2 | undefined;
  /** All non-deleted templates for this module, newest first. */
  templates: FilterTemplateDBV2[];
  error: Error | null;
  /** Create a new template. Returns the generated `id`. */
  saveTemplate: (name: string, filters: Record<string, FilterValueV2>) => Promise<string>;
  /** Overwrite filters on an existing template (bumps `updatedAt` & `version`). */
  updateTemplate: (
    id: string,
    changes: Partial<Pick<FilterTemplateDBV2, 'name' | 'filters'>>
  ) => Promise<void>;
  /** Soft-delete a template. */
  deleteTemplate: (id: string) => Promise<void>;
  /** Promote a template to "latest" by bumping its `updatedAt`. */
  applyTemplate: (id: string) => Promise<void>;
}

/**
 * Manage per-module filter templates stored in IndexedDB.
 *
 * The "latest" template is determined by the highest `updatedAt` among
 * non-deleted records for the given `module`, resolved via the compound
 * index `[module+deleted+updatedAt]` in a single seek.
 *
 * @example
 * ```tsx
 * const { latestTemplate, templates, saveTemplate } = useFilterTemplate('orders');
 *
 * // Apply latest on mount
 * useEffect(() => {
 *   if (latestTemplate) applyFilters(latestTemplate.filters);
 * }, [latestTemplate]);
 * ```
 */
export function usePersistentFilterTemplate(module: string): UsePersistentFilterTemplateReturnV2 {
  const tableRef = React.useRef(filterTemplateDB.templates);

  // ── Reactive reads ──────────────────────────────────────────────────────
  const { data: queryResult, error } = useLiveQuery(
    async () => {
      const table = tableRef.current;

      // Compound index [module+deletedAt+updatedAt]: seek where module=X, deletedAt=0.
      // Each terminal operation gets its own Collection instance — Dexie's reverse()
      // mutates the collection in place, so sharing one instance across two concurrent
      // terminal ops corrupts the cursor direction for both.
      const [templates, latest] = await Promise.all([
        // .reverse().toArray() walks the compound index from highest updatedAt down —
        // no in-memory re-sort needed (unlike .reverse().sortBy() which re-sorts ASC).
        table
          .where('[module+deletedAt+updatedAt]')
          .between(
            [module, DELETED_AT_DEFAULT_VALUE, Number.NEGATIVE_INFINITY],
            [module, DELETED_AT_DEFAULT_VALUE, Number.POSITIVE_INFINITY]
          )
          .reverse()
          .toArray(),
        // Forward cursor → .last() returns the record with the highest updatedAt.
        table
          .where('[module+deletedAt+updatedAt]')
          .between(
            [module, DELETED_AT_DEFAULT_VALUE, Number.NEGATIVE_INFINITY],
            [module, DELETED_AT_DEFAULT_VALUE, Number.POSITIVE_INFINITY]
          )
          .last(),
      ]);

      return { templates, latest };
    },
    [module],
    { templates: [] as FilterTemplateDBV2[], latest: undefined as FilterTemplateDBV2 | undefined }
  );

  // ── Mutations ───────────────────────────────────────────────────────────

  const saveTemplate = async (name: string, filters: Record<string, FilterValueV2>) => {
    const now = Date.now();
    const id = crypto.randomUUID();
    await tableRef.current.add({
      id,
      module,
      name,
      filters,
      createdAt: now,
      updatedAt: now,
      deletedAt: DELETED_AT_DEFAULT_VALUE,
      isSynced: false,
      version: CURRENT_DB_VERSION,
    });
    return id;
  };

  const updateTemplate = async (
    id: string,
    changes: Partial<Pick<FilterTemplateDBV2, 'name' | 'filters'>>
  ) => {
    const existing = await tableRef.current.get(id);
    if (!existing) return;
    await tableRef.current.update(id, {
      ...changes,
      updatedAt: Date.now(),
      version: existing.version + 1,
      isSynced: false,
    });
  };

  const deleteTemplate = async (id: string) => {
    await tableRef.current.update(id, {
      deletedAt: Date.now(),
      isSynced: false,
    });
  };

  const applyTemplate = async (id: string) => {
    await tableRef.current.update(id, { updatedAt: Date.now() });
  };

  return {
    latestTemplate: queryResult?.latest,
    templates: queryResult?.templates ?? [],
    error,
    saveTemplate,
    updateTemplate,
    deleteTemplate,
    applyTemplate,
  };
}

import { useEffect, useRef, useState } from 'react';

/** Detects when a sticky element is "stuck" at the top using a sentinel + IntersectionObserver */
export function useStickyObserver() {
  const sentinelRef = useRef<HTMLDivElement>(null);
  const [isStuck, setIsStuck] = useState(false);

  useEffect(() => {
    const sentinel = sentinelRef.current;
    if (!sentinel) return;

    const observer = new IntersectionObserver(
      (entries) => setIsStuck(!entries[0]?.isIntersecting),
      { threshold: 1.0 }
    );

    observer.observe(sentinel);
    return () => observer.disconnect();
  }, []);

  return { sentinelRef, isStuck };
}

import { useState, useEffect, useRef } from 'react';
import { toast } from 'sonner';
import { usePersistentFilterTemplate } from './use-persistent-filter-template';
import type { FilterTemplateDBV2 } from './use-persistent-filter-template';
import type { FilterValueV2 } from '../types';
import { areFilterValuesEqual } from '../utils/filter-value';
import type { FilterPanelLocaleV2 } from '../i18n';

interface UseTemplateManagerOptionsV2 {
  module: string | undefined;
  values: Record<string, FilterValueV2>;
  defaultValues: Record<string, FilterValueV2>;
  onApplyTemplate?: (filters: Record<string, FilterValueV2>) => void;
  onActiveTemplateChange?: (template: FilterTemplateDBV2 | undefined) => void;
  locale: FilterPanelLocaleV2;
}

export function useTemplateManager({
  module,
  values,
  defaultValues,
  onApplyTemplate,
  onActiveTemplateChange,
  locale,
}: UseTemplateManagerOptionsV2) {
  // Only call useFilterTemplate when module is provided.
  // When module is undefined we pass a stable placeholder — the hook will
  // simply return an empty template list (no records match "").
  const {
    latestTemplate,
    templates,
    saveTemplate: dbSave,
    updateTemplate: dbUpdate,
    deleteTemplate: dbDelete,
    applyTemplate: dbApply,
  } = usePersistentFilterTemplate(module ?? '');

  const enabled = !!module;

  // ── UI state ────────────────────────────────────────────────────────
  const [saveDialogOpen, setSaveDialogOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [templateToDelete, setTemplateToDelete] = useState<FilterTemplateDBV2 | null>(null);
  const [renameDialogOpen, setRenameDialogOpen] = useState(false);
  const [templateToRename, setTemplateToRename] = useState<FilterTemplateDBV2 | null>(null);
  const [activeTemplateId, setActiveTemplateId] = useState<string | undefined>(undefined);

  // ── Auto-apply latest template on mount ─────────────────────────────
  const appliedRef = useRef(false);

  useEffect(() => {
    if (!enabled || appliedRef.current) {
      return;
    }

    if (latestTemplate && onApplyTemplate) {
      onApplyTemplate(latestTemplate.filters);
      setActiveTemplateId(latestTemplate.id);
      onActiveTemplateChange?.(latestTemplate);
      appliedRef.current = true;
    }
  }, [enabled, latestTemplate, onApplyTemplate]);

  // ── Dirty check: compare current values against reference ──────────
  const activeTemplate = templates.find((t) => t.id === activeTemplateId);
  const referenceValues = activeTemplate ? activeTemplate.filters : defaultValues;
  const hasChangeFilter = Object.keys(values).some(
    (key) => !areFilterValuesEqual(values[key], referenceValues[key])
  );

  // ── Handlers ────────────────────────────────────────────────────────

  const resetToDefaultValue = () => {
    onApplyTemplate?.(defaultValues);
    setActiveTemplateId(undefined);
    onActiveTemplateChange?.(undefined);
  };

  const handleSave = async (name: string) => {
    if (!enabled) return;
    const id = await dbSave(name, values);
    setActiveTemplateId(id);
    setSaveDialogOpen(false);
  };

  const handleUpdate = async () => {
    if (!enabled || !activeTemplate) return;
    await dbUpdate(activeTemplate.id, { filters: values });
    toast.success(locale.templateUpdatedToast(activeTemplate.name));
  };

  const handleSelect = async (template: FilterTemplateDBV2) => {
    if (!enabled) return;

    // Toggle: clicking the already-active template unselects it
    if (activeTemplateId === template.id) {
      resetToDefaultValue();
      return;
    }

    await dbApply(template.id);
    setActiveTemplateId(template.id);
    onApplyTemplate?.(template.filters);
    onActiveTemplateChange?.(template);
  };

  const handleRequestDelete = (template: FilterTemplateDBV2) => {
    setTemplateToDelete(template);
    setDeleteDialogOpen(true);
  };

  const handleConfirmDelete = async () => {
    if (!templateToDelete) return;
    if (templateToDelete.id === activeTemplateId) {
      resetToDefaultValue();
    }
    await dbDelete(templateToDelete.id);
    setTemplateToDelete(null);
    setDeleteDialogOpen(false);
  };

  const handleCancelDelete = () => {
    setTemplateToDelete(null);
    setDeleteDialogOpen(false);
  };

  const handleRequestRename = (template: FilterTemplateDBV2) => {
    setTemplateToRename(template);
    setRenameDialogOpen(true);
  };

  const handleConfirmRename = async (name: string) => {
    if (!templateToRename) return;
    await dbUpdate(templateToRename.id, { name });
    toast.success(locale.templateRenamedToast(name));
    setTemplateToRename(null);
    setRenameDialogOpen(false);
  };

  const handleCancelRename = () => {
    setTemplateToRename(null);
    setRenameDialogOpen(false);
  };

  const openSaveDialog = () => {
    setSaveDialogOpen(true);
  };
  const closeSaveDialog = () => {
    setSaveDialogOpen(false);
  };

  return {
    enabled,
    templates,
    latestTemplate,
    activeTemplateId,
    activeTemplate,
    hasChangeFilter,

    // Save dialog
    saveDialogOpen,
    openSaveDialog,
    closeSaveDialog,
    handleSave,

    // Update in place
    handleUpdate,

    // Template selection
    handleSelect,

    // Delete dialog
    deleteDialogOpen,
    templateToDelete,
    handleRequestDelete,
    handleConfirmDelete,
    handleCancelDelete,

    // Rename dialog
    renameDialogOpen,
    templateToRename,
    handleRequestRename,
    handleConfirmRename,
    handleCancelRename,
  };
}

import { createContext, useContext } from 'react';

export interface FilterPanelLocaleV2 {
  // ── Template section ────────────────────────────────────────────────
  /** Label above the template chips row. Default: "Saved Templates" */
  savedTemplatesLabel: string;

  // ── Template chip ───────────────────────────────────────────────────
  /** Shown when no templates have been saved yet. Default: "No saved templates" */
  emptyTemplatesTitle: string;
  /** Sub-text shown in the empty state. Default: "Save your current filters to create one." */
  emptyTemplatesSubtitle: string;
  /** Name shown in the chip when no template is active. Default: "Default" */
  defaultTemplateName: string;
  /** Save button label in the chip row. Default: "Save" */
  saveButtonLabel: string;
  /** "Save as new" option in the save popover. Default: "Save as New..." */
  saveAsNewLabel: string;
  /**
   * "Update existing" option in the save popover.
   * Receives the active template name.
   * Default: (name) => `Update "${name}"`
   */
  updateTemplateLabel: (name: string) => string;

  // ── Save-template dialog ─────────────────────────────────────────────
  /** Dialog heading. Default: "Save Template" */
  saveDialogTitle: string;
  /** Dialog description. Default: "Give your current filter configuration a name so you can reuse it later." */
  saveDialogDescription: string;
  /** Label for the template-name input. Default: "Template name" */
  templateNameLabel: string;
  /** Placeholder for the template-name input. Default: "e.g. Monthly sales report" */
  templateNamePlaceholder: string;
  /** Save button inside the dialog. Default: "Save" */
  saveLabel: string;

  // ── Delete-template dialog ───────────────────────────────────────────
  /** Dialog heading. Default: "Delete Template" */
  deleteDialogTitle: string;
  /**
   * Body text for the delete confirmation dialog.
   * Receives the template name to delete.
   * Default: (name) => `Are you sure you want to delete "${name}"? This action cannot be undone.`
   */
  deleteDialogDescription: (name: string) => string;
  /** Delete button label. Default: "Delete" */
  deleteLabel: string;

  // ── Shared ───────────────────────────────────────────────────────────
  /** Cancel button shared across dialogs. Default: "Cancel" */
  cancelLabel: string;

  // ── Toast messages ───────────────────────────────────────────────────
  /**
   * Toast shown after successfully updating a template.
   * Receives the template name.
   * Default: (name) => `Template "${name}" updated`
   */
  templateUpdatedToast: (name: string) => string;

  // ── Rename-template dialog ───────────────────────────────────────────
  /** Dialog heading. Default: "Rename Template" */
  renameDialogTitle: string;
  /** Rename confirm button label. Default: "Rename" */
  renameLabel: string;
  /**
   * Toast shown after successfully renaming a template.
   * Receives the new template name.
   * Default: (name) => `Template "${name}" renamed`
   */
  templateRenamedToast: (name: string) => string;
}

export const defaultFilterPanelLocaleV2: FilterPanelLocaleV2 = {
  savedTemplatesLabel: 'Saved Templates',

  emptyTemplatesTitle: 'No saved templates',
  emptyTemplatesSubtitle: 'Save your current filters to create one.',
  defaultTemplateName: 'Default',
  saveButtonLabel: 'Save',
  saveAsNewLabel: 'Save as New...',
  updateTemplateLabel: (name) => `Update "${name}"`,

  saveDialogTitle: 'Save Template',
  saveDialogDescription: 'Give your current filter configuration a name so you can reuse it later.',
  templateNameLabel: 'Template name',
  templateNamePlaceholder: 'e.g. Monthly sales report',
  saveLabel: 'Save',

  deleteDialogTitle: 'Delete Template',
  deleteDialogDescription: (name) =>
    `Are you sure you want to delete "${name}"? This action cannot be undone.`,
  deleteLabel: 'Delete',

  cancelLabel: 'Cancel',

  templateUpdatedToast: (name) => `Template "${name}" updated`,

  renameDialogTitle: 'Rename Template',
  renameLabel: 'Rename',
  templateRenamedToast: (name) => `Template "${name}" renamed`,
};

export const FilterPanelLocaleContextV2 = createContext<FilterPanelLocaleV2>(
  defaultFilterPanelLocaleV2
);

export function useFilterPanelLocaleV2(): FilterPanelLocaleV2 {
  return useContext(FilterPanelLocaleContextV2);
}

