  | number
  | {
      sm?: number;
      md?: number;
      lg?: number;
      xl?: number;
      '2xl'?: number;
    };

export interface BaseFilterOptionV2 {
  value: string;
  label: string;
}

export interface TabFilterConfigV2 {
