                    </span>

                    {filter.type === 'tabs' && (
                      <Tabs
                        value={values[filter.key] as string}
                        onValueChange={(value) => {
                          onChange(filter.key, value);
                          filter.onChange?.(value);
                        }}
                      >
                        <TabsList>
                          {filter.options.map((option) => (
                            <TabsTrigger
                              disabled={filter.disable}
                              key={option.value}
                              value={option.value}
                            >
                              {option.label}
                            </TabsTrigger>
                          ))}
                        </TabsList>
                      </Tabs>
                    )}

                    {filter.type === 'select' && filter.asyncSelectProps && (
                      <AsyncSelect
