import { useState, type ChangeEvent, type ComponentProps, useEffect, useCallback } from 'react';
import { Input } from '../../ui/forms/input';

import { useDebounceCallback } from '../../../hooks/use-debounce-callback';

export interface DebounceInputProps extends Omit<ComponentProps<typeof Input>, 'onChange'> {
  debounceMs?: number;
  onChange?: (value: string) => void;
}

export const DebounceInput = ({
  debounceMs = 500,
  onChange,
  ...inputProps
}: DebounceInputProps) => {
  const [value, setValue] = useState(inputProps.value);

  const debouncedChange = useDebounceCallback((event: ChangeEvent<HTMLInputElement>) => {
    onChange?.(event.target.value);
  }, debounceMs);

  const handleChange = useCallback((event: ChangeEvent<HTMLInputElement>) => {
    setValue(event.target.value);
    debouncedChange?.(event);
  }, []);

  useEffect(() => {
    setValue(inputProps.value);
  }, [inputProps.value]);

  return <Input {...inputProps} value={value} onChange={handleChange} />;
};

import { Input } from '../../ui/forms/input';
import { Check, Plus, X } from 'lucide-react';
import { type ReactNode, useState, useEffect } from 'react';

export interface EditableProps {
  /** The wrapped component (e.g., Select) */
  children: ReactNode;
  /** Callback when new value is added */
  onAdd: (value: string) => void;
  /** Input placeholder text */
  placeholder?: string;
  /** Disable add functionality */
  disabled?: boolean;
  /** Custom add icon */
  addIcon?: ReactNode;
  /** Custom class for the input */
  inputClassName?: string;
  /** Custom class for the container */
  className?: string;
  /** Default value */
  defaultValue?: string;
}

export const Editable = ({
  children,
  defaultValue,
  onAdd,
  placeholder = 'Enter new value...',
  disabled = false,
  addIcon,
  inputClassName,
  className,
}: EditableProps) => {
  const [isEditing, setIsEditing] = useState(false);
  const [inputValue, setInputValue] = useState(defaultValue || '');

  useEffect(() => {
    setInputValue(defaultValue || '');
  }, [defaultValue]);

  const handleSubmit = () => {
    const trimmedValue = inputValue.trim();
    if (trimmedValue) {
      onAdd(trimmedValue);
    }
    setInputValue('');
    setIsEditing(false);
  };

  const handleCancel = () => {
    setInputValue(defaultValue || '');
    setIsEditing(false);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleSubmit();
    } else if (e.key === 'Escape') {
      e.preventDefault();
      handleCancel();
    }
  };

  if (isEditing) {
    return (
      <div className={className}>
        <Input
          autoFocus
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={placeholder}
          className={inputClassName}
          suffixIcon={
            <div className="flex items-center gap-1">
              <button
                type="button"
                onClick={handleSubmit}
                disabled={!inputValue.trim()}
                className="rounded p-0.5 text-green-600 hover:bg-green-100 dark:hover:bg-green-900/30"
                aria-label="Confirm"
              >
                <Check className="h-4 w-4" />
              </button>
              <button
                type="button"
                onClick={handleCancel}
                className="rounded p-0.5 text-red-600 hover:bg-red-100 disabled:cursor-not-allowed disabled:opacity-50 dark:hover:bg-red-900/30"
                aria-label="Cancel"
              >
                <X className="h-4 w-4" />
              </button>
            </div>
          }
        />
      </div>
    );
  }

  return (
    <div className={`flex items-center gap-2 ${className ?? ''}`}>
      <div className="flex-1">{children}</div>
      {!disabled && (
        <button
          type="button"
          onClick={() => setIsEditing(true)}
          className="flex h-9 w-9 shrink-0 items-center justify-center rounded-md border border-input bg-transparent text-muted-foreground transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          aria-label="Add new option"
        >
          {addIcon ?? <Plus className="h-4 w-4" />}
        </button>
      )}
    </div>
  );
};

import { useWatchField } from '../../../hooks/use-watch-field';
import { FormField } from '../../ui/forms/form';
import type { ReactNode } from 'react';
import type {
  ControllerFieldState,
  ControllerRenderProps,
  FieldPath,
  FieldValues,
  UseFormStateReturn,
} from 'react-hook-form';
import { useFormContext } from 'react-hook-form';

type RenderProps<
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
> = {
  field: ControllerRenderProps<TFieldValues, TName>;
  fieldState: ControllerFieldState;
  formState: UseFormStateReturn<TFieldValues>;
  watchedValues: unknown[];
  disabled: boolean;
  value: TFieldValues[TName];
  onChange?: (value: TFieldValues[TName]) => void;
};

type FormControlProps<
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
> = {
  /** Field name in the form */
  name: TName;
  /** Field names to watch for changes */
  watchName?: FieldPath<TFieldValues>[];
  /** Whether the field is disabled */
  disabled?: boolean;

  resetOnChange?: FieldPath<TFieldValues>[];
  /** React Hook Form validation rules */
  rules?: Parameters<typeof FormField<TFieldValues, TName>>[0]['rules'];
  /** Render function for custom control UI */
  render: (props: RenderProps<TFieldValues, TName>) => ReactNode;
};

export const FormControl = <
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
>({
  name,
  watchName,
  disabled = false,
  resetOnChange,
  rules,
  render,
}: FormControlProps<TFieldValues, TName>) => {
  const form = useFormContext<TFieldValues>();

  const { watchedValues } = useWatchField({
    watchName: watchName as string[] | undefined,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    control: form.control as any,
    enabled: !disabled,
  });

  const handleChange = () => {
    if (resetOnChange) {
      resetOnChange.forEach((fieldName) => {
        form.setValue(fieldName, undefined as TFieldValues[TName]);
      });
    }
  };

  return (
    <FormField<TFieldValues, TName>
      control={form.control}
      name={name}
      rules={rules}
      render={({ field, fieldState, formState }) => (
        <>
          {render({
            field,
            fieldState,
            formState,
            watchedValues,
            disabled,
            value: field.value,
            onChange: (value: any) => {
              field.onChange(value);
              handleChange();
            },
          })}
        </>
      )}
    />
  );
};

import type { ComponentProps } from 'react';
import { ControlWrapper, FormField } from '../../ui/forms/form';
import type { Input } from '../../ui/forms/input';
import { useFormContext } from 'react-hook-form';

import { DebounceInput } from './debounce-input';

export interface FormDebounceInputProps extends Omit<ComponentProps<typeof Input>, 'onChange'> {
  name: string;
  label?: string;
  required?: boolean;
  debounceMs?: number;
  onChange?: (value: string) => void;
}

export const FormDebounceInput = ({
  name,
  label,
  required,
  debounceMs = 500,
  onChange,
  ...inputProps
}: FormDebounceInputProps) => {
  const form = useFormContext();

  return (
    <FormField
      control={form.control}
      name={name}
      render={({ field }) => (
        <ControlWrapper label={label} required={required}>
          <DebounceInput
            {...inputProps}
            value={field.value ?? ''}
            onChange={(value) => {
              field.onChange(value);
              onChange?.(value);
            }}
            onBlur={field.onBlur}
            debounceMs={debounceMs}
          />
        </ControlWrapper>
      )}
    />
  );
};

