import type { ValueEditorProps } from 'react-querybuilder';
import { Input } from '../../ui/forms/input';
import { Textarea } from '../../ui/forms/textarea';
import { Checkbox } from '../../ui/forms/checkbox';
import { Switch } from '../../ui/forms/switch';
import { RadioGroup, RadioGroupItem } from '../../ui/forms/radio-group';
import { Label } from '../../ui/display/label';
import { ShadcnValueSelector } from './shadcn-value-selector';

export type ShadcnValueEditorProps = ValueEditorProps & {
  extraProps?: Record<string, unknown>;
};

export function ShadcnValueEditor(props: ShadcnValueEditorProps) {
  const {
    fieldData,
    operator,
    value,
    handleOnChange,
    title,
    className,
    type,
    inputType,
    values = [],
    disabled,
    path,
    level,
    schema,
    extraProps = {},
  } = props;

  // Handle null/notNull operators
  if (operator === 'null' || operator === 'notNull') {
    return null;
  }

  // Handle between/notBetween operators
  if (
    (operator === 'between' || operator === 'notBetween') &&
    (type === 'select' || type === 'text')
  ) {
    const valueArray = Array.isArray(value) ? value : [value, ''];

    const handleBetweenChange = (val: string, idx: number) => {
      const newValue = [...valueArray];
      newValue[idx] = val;
      handleOnChange(newValue.join(','));
    };

    const editors = ['from', 'to'].map((pos, idx) => {
      if (type === 'text') {
        return (
          <Input
            key={pos}
            type={inputType || 'text'}
            className="w-[100px]"
            value={valueArray[idx] ?? ''}
            onChange={(e) => handleBetweenChange(e.target.value, idx)}
            disabled={disabled}
            placeholder={pos}
            {...extraProps}
          />
        );
      }
      return (
        <ShadcnValueSelector
          key={pos}
          options={values}
          value={valueArray[idx] ?? ''}
          handleOnChange={(v) => handleBetweenChange(v, idx)}
          disabled={disabled}
          path={path}
          level={level}
          schema={schema}
          {...extraProps}
        />
      );
    });

    return (
      <span className="flex items-center gap-2">
        {editors[0]}
        <span className="text-muted-foreground">and</span>
        {editors[1]}
      </span>
    );
  }

  // Handle different input types
  switch (type) {
    case 'select':
    case 'multiselect':
      return (
        <ShadcnValueSelector
          className={className}
          title={title}
          options={values}
          value={value}
          handleOnChange={handleOnChange}
          disabled={disabled}
          multiple={type === 'multiselect'}
          path={path}
          level={level}
          schema={schema}
          {...extraProps}
        />
      );

    case 'textarea':
      return (
        <Textarea
          className={className}
          value={value}
          onChange={(e) => handleOnChange(e.target.value)}
          disabled={disabled}
          title={title}
          placeholder={fieldData?.placeholder}
          {...extraProps}
        />
      );

    case 'switch':
      return (
        <Switch
          className={className}
          checked={!!value}
          onCheckedChange={handleOnChange}
          disabled={disabled}
          title={title}
          {...extraProps}
        />
      );

    case 'checkbox':
      return (
        <Checkbox
          className={className}
          checked={!!value}
          onCheckedChange={handleOnChange}
          disabled={disabled}
          title={title}
          {...extraProps}
        />
      );

    case 'radio':
      return (
        <RadioGroup
          className={className}
          value={value}
          onValueChange={handleOnChange}
          disabled={disabled}
        >
          {values.map((opt) => (
            <div key={opt.name} className="flex items-center space-x-2">
              <RadioGroupItem value={opt.name ?? ''} id={opt.name} disabled={opt.disabled} />
              <Label htmlFor={opt.name}>{opt.label}</Label>
            </div>
          ))}
        </RadioGroup>
      );

    default:
      return (
        <Input
          type={inputType || 'text'}
          className={`w-[180px] ${className ?? ''}`}
          value={value}
          onChange={(e) => handleOnChange(e.target.value)}
          disabled={disabled}
          title={title}
          placeholder={fieldData?.placeholder}
          {...extraProps}
        />
      );
  }
}

ShadcnValueEditor.displayName = 'ShadcnValueEditor';

import type { VersatileSelectorProps } from 'react-querybuilder';
import {
  Select,
  SelectContent,
  SelectTrigger,
  SelectValue,
  SelectGroup,
} from '../../ui/forms/select';

import { toSelectOptions } from './utils';
import {
  MultiSelect,
  type MultiSelectGroup,
  type MultiSelectOption,
} from '../../patterns/multi-select';

export type ShadcnValueSelectorProps = VersatileSelectorProps &
  Omit<React.ComponentPropsWithoutRef<typeof Select>, 'multiple'>;

export function ShadcnValueSelector(props: ShadcnValueSelectorProps) {
  const { className, handleOnChange, options, value, title, disabled, multiple } = props;
  // Use MultiSelect for multiple selection mode
  if (multiple) {
    const valueArray = Array.isArray(value) ? value : value ? [value] : [];
    return (
      <MultiSelect
        options={options as MultiSelectOption[] | MultiSelectGroup[]}
        value={valueArray}
        onChange={(newValue) => handleOnChange(newValue.join(','))}
        disabled={disabled}
        placeholder="Select..."
      />
    );
  }

  return (
    <Select
      items={options as { value: string; label: string }[]}
      value={value as string}
      onValueChange={handleOnChange}
      disabled={disabled}
    >
      <SelectTrigger className={`w-[180px] ${className ?? ''}`} title={title}>
        <SelectValue placeholder="Select..." />
      </SelectTrigger>
      <SelectContent>
        <SelectGroup>{toSelectOptions(options)}</SelectGroup>
      </SelectContent>
    </Select>
  );
}

ShadcnValueSelector.displayName = 'ShadcnValueSelector';

import type { OptionList } from 'react-querybuilder';
import { isOptionGroupArray } from 'react-querybuilder';
import { SelectGroup, SelectItem, SelectLabel } from '../../ui/forms/select';

export const toSelectOptions = (list: OptionList) => {
  if (isOptionGroupArray(list)) {
    return list.map((group) => (
      <SelectGroup key={group.label}>
        <SelectLabel>{group.label}</SelectLabel>
        {group.options.map((opt) => (
          <SelectItem key={opt.name} value={opt.name ?? ''} disabled={!!opt.disabled}>
            {opt.label}
          </SelectItem>
        ))}
      </SelectGroup>
    ));
  }
  if (Array.isArray(list)) {
    return list.map((opt) => (
      <SelectItem key={opt.name} value={opt.name ?? ''} disabled={!!opt.disabled}>
        {opt.label}
      </SelectItem>
    ));
  }
  return null;
};

'use client';

import type React from 'react';
import { Timeline, TimelineItem } from './timeline';
import { motion } from 'framer-motion';
import type { TimelineElement } from './types';

interface TimelineLayoutProps {
  items: TimelineElement[];
  size?: 'sm' | 'md' | 'lg';
  iconColor?: 'primary' | 'secondary' | 'muted' | 'accent';
  customIcon?: React.ReactNode;
  animate?: boolean;
  connectorColor?: 'primary' | 'secondary' | 'muted' | 'accent';
  className?: string;
}

export const TimelineLayout = ({
  items,
  size = 'md',
  iconColor,
  customIcon,
  animate = true,
  connectorColor,
  className,
}: TimelineLayoutProps) => {
  return (
    <Timeline size={size} className={className}>
      {[...items].reverse().map((item, index) => (
        <motion.div
          key={index}
          initial={animate ? { opacity: 0, y: 20 } : false}
          animate={animate ? { opacity: 1, y: 0 } : false}
          transition={{
            duration: 0.5,
            delay: index * 0.1,
            ease: 'easeOut',
          }}
        >
          <TimelineItem
            date={item.date}
            title={item.title}
            description={item.description}
            icon={item.icon || customIcon}
            iconColor={item.color || iconColor}
            connectorColor={item.color || connectorColor}
            showConnector={index !== items.length - 1}
          />
        </motion.div>
      ))}
    </Timeline>
  );
};

'use client';

import * as React from 'react';

import { cva, type VariantProps } from 'class-variance-authority';
import { motion, type HTMLMotionProps } from 'framer-motion';
import { AlertCircle, Loader2 } from 'lucide-react';
import { cn } from '../../../lib/utils';
import type { TimelineColor } from './types';

const timelineVariants = cva('relative flex flex-col', {
  variants: {
    size: {
      sm: 'gap-4',
      md: 'gap-6',
      lg: 'gap-8',
    },
  },
  defaultVariants: {
    size: 'md',
  },
});

/**
 * Timeline component props interface
 * @interface TimelineProps
 * @extends {React.HTMLAttributes<HTMLOListElement>}
 * @extends {VariantProps<typeof timelineVariants>}
 */
interface TimelineProps
  extends React.HTMLAttributes<HTMLOListElement>,
    VariantProps<typeof timelineVariants> {
  /** Size of the timeline icons */
  iconsize?: 'sm' | 'md' | 'lg';
}

/**
 * Timeline component for displaying a vertical list of events or items
 * @component
 */
const Timeline = React.forwardRef<HTMLOListElement, TimelineProps>(
  ({ className, iconsize, size, children, ...props }, ref) => {
    const items = React.Children.toArray(children);

    if (items.length === 0) {
      return <TimelineEmpty />;
    }

    return (
      <ol
        ref={ref}
        aria-label="Timeline"
        className={cn(
          timelineVariants({ size }),
          'relative mx-auto min-h-[600px] w-full max-w-2xl py-8',
          className
        )}
        {...props}
      >
        {React.Children.map(children, (child, index) => {
          if (
            React.isValidElement(child) &&
            typeof child.type !== 'string' &&
            'displayName' in child.type &&
            child.type.displayName === 'TimelineItem'
          ) {
            return React.cloneElement(child, {
              iconsize,
              showConnector: index !== items.length - 1,
            } as React.ComponentProps<typeof TimelineItem>);
          }
          return child;
        })}
      </ol>
    );
  }
);
Timeline.displayName = 'Timeline';

/**
 * TimelineItem component props interface
 * @interface TimelineItemProps
 * @extends {Omit<HTMLMotionProps<"li">, "ref">}
 */
interface TimelineItemProps extends Omit<HTMLMotionProps<'li'>, 'ref'> {
  /** Date string for the timeline item */
  date?: string;
  /** Title of the timeline item */
  title?: string;
  /** Description text */
  description?: React.ReactNode;
  /** Custom icon element */
  icon?: React.ReactNode;
  /** Color theme for the icon */
  iconColor?: TimelineColor;
  /** Current status of the item */
  status?: 'completed' | 'in-progress' | 'pending';
  /** Color theme for the connector line */
  connectorColor?: TimelineColor;
  /** Whether to show the connector line */
  showConnector?: boolean;
  /** Size of the icon */
  iconsize?: 'sm' | 'md' | 'lg';
  /** Loading state */
  loading?: boolean;
  /** Error message */
  error?: string;
}

const TimelineItem = React.forwardRef<HTMLLIElement, TimelineItemProps>(
  (
    {
      className,
      date,
      title,
      description,
      icon,
      iconColor,
      status = 'completed',
      connectorColor,
      showConnector = true,
      iconsize,
      loading,
      error,
      // Omit unused Framer Motion props
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      initial,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      animate,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      transition,
      ...props
    },
    ref
  ) => {
    const commonClassName = cn('relative mb-8 w-full last:mb-0', className);

    // Loading State
    if (loading) {
      return (
        <motion.li
          ref={ref}
          className={commonClassName}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          role="status"
          {...props}
        >
          <div className="grid grid-cols-[minmax(auto,8rem)_auto_1fr] items-start px-4">
            <div className="pr-4 text-right">
              <div className="h-4 w-24 animate-pulse rounded bg-muted" />
            </div>

            <div className="mx-3 flex flex-col items-center justify-start gap-y-2">
              <div className="relative flex h-8 w-8 animate-pulse items-center justify-center rounded-full bg-muted ring-8 ring-background">
                <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
              </div>
              {showConnector && <div className="h-full w-0.5 animate-pulse bg-muted" />}
            </div>

            <div className="flex flex-col gap-2 pl-2">
              <div className="space-y-2">
                <div className="h-4 w-24 animate-pulse rounded bg-muted" />
                <div className="h-3 w-48 animate-pulse rounded bg-muted" />
              </div>
            </div>
          </div>
        </motion.li>
      );
    }

    // Error State
    if (error) {
      return (
        <motion.li
          ref={ref}
          className={cn(commonClassName, 'border border-destructive/50 bg-destructive/10')}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          role="alert"
          {...props}
        >
          <div className="grid grid-cols-[minmax(auto,8rem)_auto_1fr] items-start px-4">
            <div className="pr-4 text-right">
              <TimelineTime className="text-destructive">{date}</TimelineTime>
            </div>

            <div className="mx-3 flex flex-col items-center justify-start gap-y-2">
              <div className="relative flex h-8 w-8 items-center justify-center rounded-full bg-destructive/20 ring-8 ring-background">
                <AlertCircle className="h-4 w-4 text-destructive" />
              </div>
              {showConnector && <TimelineConnector status="pending" className="h-full" />}
            </div>

            <div className="flex flex-col gap-2 pl-2">
              <TimelineHeader>
                <TimelineTitle className="text-destructive">{title || 'Error'}</TimelineTitle>
              </TimelineHeader>
              <TimelineDescription className="text-destructive">{error}</TimelineDescription>
            </div>
          </div>
        </motion.li>
      );
    }

    const content = (
      <div
        className="grid grid-cols-[1fr_auto_1fr] items-start gap-4"
        {...(status === 'in-progress' ? { 'aria-current': 'step' } : {})}
      >
        {/* Date */}
        <div className="flex flex-col justify-start pt-2">
          <TimelineTime className="pr-4 text-right">{date}</TimelineTime>
        </div>

        {/* Timeline dot and connector */}
        <div className="flex flex-col items-center">
          <div className="relative z-10">
            <TimelineIcon icon={icon} color={iconColor} status={status} iconSize={iconsize} />
          </div>
          {showConnector && <div className="mt-2 h-16 w-0.5 bg-border" />}
        </div>

        {/* Content */}
        <TimelineContent>
          <TimelineHeader>
            <TimelineTitle>{title}</TimelineTitle>
          </TimelineHeader>
          <TimelineDescription>{description}</TimelineDescription>
        </TimelineContent>
      </div>
    );

    // Filter out Framer Motion specific props
    const {
      style,
      onDrag,
      onDragStart,
      onDragEnd,
      onAnimationStart,
      onAnimationComplete,
      transformTemplate,
      whileHover,
      whileTap,
      whileDrag,
      whileFocus,
      whileInView,
      ...filteredProps
    } = props;

    return (
      <li ref={ref} className={commonClassName} {...filteredProps}>
        {content}
      </li>
    );
  }
);
TimelineItem.displayName = 'TimelineItem';

interface TimelineTimeProps extends React.HTMLAttributes<HTMLTimeElement> {
  /** Date string, Date object, or timestamp */
  date?: string | Date | number;
  /** Optional format for displaying the date */
  format?: Intl.DateTimeFormatOptions;
}

const defaultDateFormat: Intl.DateTimeFormatOptions = {
  year: 'numeric',
  month: 'short',
  day: '2-digit',
};

const TimelineTime = React.forwardRef<HTMLTimeElement, TimelineTimeProps>(
  ({ className, date, format, children, ...props }, ref) => {
    const formattedDate = React.useMemo(() => {
      if (!date) return '';

      try {
        const dateObj = new Date(date);
        if (isNaN(dateObj.getTime())) return '';

        return new Intl.DateTimeFormat('en-US', {
          ...defaultDateFormat,
          ...format,
        }).format(dateObj);
      } catch (error) {
        console.error('Error formatting date:', error);
        return '';
      }
    }, [date, format]);

    return (
      <time
        ref={ref}
        dateTime={date ? new Date(date).toISOString() : undefined}
        className={cn('font-medium text-muted-foreground text-sm tracking-tight', className)}
        {...props}
      >
        {children || formattedDate}
      </time>
    );
  }
);
TimelineTime.displayName = 'TimelineTime';

const TimelineConnector = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement> & {
    status?: 'completed' | 'in-progress' | 'pending';
    color?: 'primary' | 'secondary' | 'muted' | 'accent';
  }
>(({ className, status = 'completed', color, ...props }, ref) => (
  <div
    ref={ref}
    className={cn(
      'w-0.5',
      {
        'bg-primary': color === 'primary' || (!color && status === 'completed'),
        'bg-muted': color === 'muted' || (!color && status === 'pending'),
        'bg-secondary': color === 'secondary',
        'bg-accent': color === 'accent',
        'bg-gradient-to-b from-primary to-muted': !color && status === 'in-progress',
      },
      className
    )}
    {...props}
  />
));
TimelineConnector.displayName = 'TimelineConnector';

const TimelineHeader = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => (
    <div ref={ref} className={cn('flex items-center gap-4', className)} {...props} />
  )
);
TimelineHeader.displayName = 'TimelineHeader';

const TimelineTitle = React.forwardRef<
  HTMLHeadingElement,
  React.HTMLAttributes<HTMLHeadingElement>
>(({ className, children, ...props }, ref) => (
  <h3
    ref={ref}
    className={cn('font-semibold text-secondary-foreground leading-none tracking-tight', className)}
    {...props}
  >
    {children}
  </h3>
));
TimelineTitle.displayName = 'TimelineTitle';

const TimelineIcon = ({
  icon,
  color = 'primary',
  iconSize = 'md',
}: {
  icon?: React.ReactNode;
  color?: 'primary' | 'secondary' | 'muted' | 'accent' | 'destructive';
  status?: 'completed' | 'in-progress' | 'pending' | 'error';
  iconSize?: 'sm' | 'md' | 'lg';
}) => {
  const sizeClasses = {
    sm: 'h-8 w-8',
    md: 'h-10 w-10',
    lg: 'h-12 w-12',
  };

  const iconSizeClasses = {
    sm: 'h-4 w-4',
    md: 'h-5 w-5',
    lg: 'h-6 w-6',
  };

  const colorClasses = {
    primary: 'bg-primary text-primary-foreground',
    secondary: 'bg-secondary text-secondary-foreground',
    muted: 'bg-muted text-muted-foreground',
    accent: 'bg-accent text-accent-foreground',
    destructive: 'bg-destructive text-destructive-foreground',
  };

  return (
    <div
      className={cn(
        'relative flex items-center justify-center rounded-full shadow-sm ring-8 ring-background',
        sizeClasses[iconSize],
        colorClasses[color]
      )}
    >
      {icon ? (
        <div className={cn('flex items-center justify-center', iconSizeClasses[iconSize])}>
          {icon}
        </div>
      ) : (
        <div className={cn('rounded-full', iconSizeClasses[iconSize])} />
      )}
    </div>
  );
};

const TimelineDescription = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLParagraphElement>
>(({ className, ...props }, ref) => (
  <p ref={ref} className={cn('max-w-sm text-muted-foreground text-sm', className)} {...props} />
));
TimelineDescription.displayName = 'TimelineDescription';

const TimelineContent = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => (
    <div ref={ref} className={cn('flex flex-col gap-2 pt-2 pl-2', className)} {...props} />
  )
);
TimelineContent.displayName = 'TimelineContent';

const TimelineEmpty = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
