import { Cross2Icon } from '@radix-ui/react-icons';
import { type Dispatch, type SetStateAction, forwardRef, useRef, useState } from 'react';
import { cn } from '../../../lib/utils';
import { Input } from '../../ui/forms/input';
import { Badge } from '../../ui/display/badge';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '../../ui/overlays/tooltip';
import { LongText } from '../long-text';

type InputTagsProps = {
  value: string[];
  onChange: Dispatch<SetStateAction<string[]>>;
  /**
   * Maximum number of tags to display before showing "+N more".
   * If not provided, all tags are shown.
   */
  maxCount?: number;
  /**
   * Maximum width for tag label before truncation
   * @default '120px'
   */
  tagLabelMaxWidth?: string;
  /**
   * Max height for wrapped tags container before enabling vertical scroll
   * @default '160px'
   */
  maxContainerHeight?: string;
} & Omit<React.ComponentProps<typeof Input>, 'value' | 'onChange'>;

export const InputTags = forwardRef<HTMLInputElement, InputTagsProps>(
  (
    {
      value,
      onChange,
      className,
      maxCount,
      tagLabelMaxWidth = '120px',
      maxContainerHeight = '160px',
      placeholder,
      ...props
    },
    ref
  ) => {
    const [pendingDataPoint, setPendingDataPoint] = useState('');
    const inputRef = useRef<HTMLInputElement | null>(null);

    const assignRefs = (node: HTMLInputElement | null) => {
      inputRef.current = node;
      if (typeof ref === 'function') {
        ref(node);
      } else if (ref) {
        ref.current = node;
      }
    };

    const normalizeTag = (tag: string) => tag.trim().replace(/\s+/g, ' ');

    const addTags = (candidateTags: string[]) => {
      if (candidateTags.length === 0) return;
      const existingTags = new Set(value);
      const nextValue = [...value];

      for (const candidate of candidateTags) {
        const normalized = normalizeTag(candidate);
        if (!normalized || existingTags.has(normalized)) continue;
        existingTags.add(normalized);
        nextValue.push(normalized);
      }

      if (nextValue.length !== value.length) {
        onChange(nextValue);
      }
    };

    const addPendingDataPoint = (shouldRefocus = true) => {
      if (!pendingDataPoint) return;
      addTags([pendingDataPoint]);
      setPendingDataPoint('');
      if (shouldRefocus) {
        inputRef.current?.focus();
      }
    };

    const visibleTags = typeof maxCount === 'number' ? value.slice(0, maxCount) : value;
    const hiddenTagCount = typeof maxCount === 'number' ? Math.max(0, value.length - maxCount) : 0;
    const hiddenTags =
      typeof maxCount === 'number' && hiddenTagCount > 0 ? value.slice(maxCount) : [];

    const clearExtraTags = () => {
      if (typeof maxCount !== 'number' || hiddenTagCount === 0) return;
      onChange(value.slice(0, maxCount));
      inputRef.current?.focus();
    };

    const removeTag = (tag: string) => {
      onChange(value.filter((item) => item !== tag));
      inputRef.current?.focus();
    };

    return (
      <TooltipProvider>
        <div
          className={cn(
            'w-full rounded-md border border-input bg-transparent px-2 py-1',
            'text-base shadow-xs transition-[color,box-shadow]',
            'focus-within:border-ring focus-within:ring-[3px] focus-within:ring-ring/50',
            'md:text-sm',
            className
          )}
        >
          <div
            className="flex max-h-full w-full flex-wrap items-center gap-1 overflow-y-auto"
            style={{ maxHeight: maxContainerHeight }}
          >
            {visibleTags.map((item) => (
              <Badge
                key={item}
                className={cn(
                  'h-6 shrink-0 whitespace-nowrap rounded-sm',
                  'bg-primary text-primary-foreground',
                  'flex items-center gap-1 px-2 py-0',
                  'border-primary/20 hover:bg-primary/90',
                  'text-xs'
                )}
              >
                <LongText maxWidth={tagLabelMaxWidth} className="leading-normal">
                  {item}
                </LongText>
                <button
                  type="button"
                  aria-label={`Remove ${item}`}
                  className="ml-0.5 flex h-3.5 w-3.5 items-center justify-center rounded-sm hover:bg-white/20 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring/70 dark:hover:bg-black/20"
                  onClick={() => removeTag(item)}
                >
                  <Cross2Icon className="h-3 w-3" />
                </button>
              </Badge>
            ))}

            {hiddenTagCount > 0 && (
              <Tooltip>
                <TooltipTrigger asChild>
                  <Badge
                    className={cn(
                      'h-6 shrink-0 whitespace-nowrap rounded-sm',
                      'bg-primary/80 text-primary-foreground',
                      'flex items-center gap-1 px-2 py-0',
                      'border-primary/20 hover:bg-primary/90',
                      'text-xs'
                    )}
                  >
                    +{hiddenTagCount} more
                    <button
                      type="button"
                      aria-label={`Clear ${hiddenTagCount} extra tags`}
                      className="ml-0.5 flex h-3.5 w-3.5 items-center justify-center rounded-sm hover:bg-white/20 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring/70 dark:hover:bg-black/20"
                      onClick={clearExtraTags}
                    >
                      <Cross2Icon className="h-3 w-3" />
                    </button>
                  </Badge>
                </TooltipTrigger>

                {hiddenTags.length > 0 && (
                  <TooltipContent sideOffset={4} className="max-w-xs">
                    <div className="flex flex-wrap gap-1">
                      {hiddenTags.map((item) => (
                        <Badge
                          key={item}
                          className={cn(
                            'h-6 shrink-0 whitespace-nowrap rounded-sm',
                            'bg-primary/80 text-primary-foreground',
                            'flex items-center gap-1 px-2 py-0',
                            'border-primary/20 hover:bg-primary/90',
                            'text-xs'
                          )}
                        >
                          <LongText maxWidth={tagLabelMaxWidth} className="leading-normal">
                            {item}
                          </LongText>
                          <button
                            type="button"
                            aria-label={`Remove ${item}`}
                            className="ml-0.5 flex h-3.5 w-3.5 items-center justify-center rounded-sm hover:bg-white/20 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring/70 dark:hover:bg-black/20"
                            onClick={() => removeTag(item)}
                          >
                            <Cross2Icon className="h-3 w-3" />
                          </button>
                        </Badge>
                      ))}
                    </div>
                  </TooltipContent>
                )}
              </Tooltip>
            )}

            <Input
              value={pendingDataPoint}
              onChange={(e) => setPendingDataPoint(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ',') {
                  e.preventDefault();
                  addPendingDataPoint();
                  return;
                }

                if (e.key === 'Backspace' && pendingDataPoint.length === 0 && value.length > 0) {
                  e.preventDefault();
                  onChange(value.slice(0, -1));
                }
              }}
              onPaste={(e) => {
                const pastedText = e.clipboardData.getData('text');
                if (!/[,\n;]/.test(pastedText)) return;
                e.preventDefault();
                addTags(pastedText.split(/[,\n;]+/g));
              }}
              onBlur={() => addPendingDataPoint(false)}
              placeholder={value.length === 0 ? placeholder : ''}
              className="h-7 min-h-0 min-w-[120px] flex-1 border-0 bg-transparent px-1 shadow-none focus-visible:ring-0"
              {...props}
              ref={assignRefs}
            />
          </div>
        </div>
      </TooltipProvider>
    );
  }
);

InputTags.displayName = 'InputTags';

import { useEffect, useRef, useState } from 'react';
import { cn } from '../../../lib/utils';
import { Popover, PopoverContent, PopoverTrigger } from '../../ui/overlays/popover';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '../../ui/overlays/tooltip';

export type LongTextMode = 'tooltip' | 'wrap' | 'translate';

type LongTextProps = {
  children: React.ReactNode;
  className?: string;
  contentClassName?: string;
  /**
   * Display mode for overflowing text.
   * @default 'tooltip'
   */
  mode?: LongTextMode;
  /**
   * Scroll speed in pixels per second (translate mode only).
   * @default 50
   */
  speed?: number;
  /**
   * Backward-compat alias for mode="wrap".
   * @default false
   */
  wrap?: boolean;

  /**
   * @deprecated Width is now driven by the parent container. This prop has no effect.
   */
  maxWidth?: string;
};

export function LongText({
  children,
  className = '',
  contentClassName = '',
  mode: modeProp = 'tooltip',
  speed = 50,
  wrap = false,
}: LongTextProps) {
  const effectiveMode: LongTextMode = wrap ? 'wrap' : modeProp;

  // Tooltip mode — invisible absolute probe for stable, resize-aware overflow detection.
  // The probe always stays in the DOM so the ResizeObserver never loses its target.
  const measureRef = useRef<HTMLSpanElement>(null);
  const [isOverflown, setIsOverflown] = useState(false);

  // Translate mode
  const containerRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLSpanElement>(null);
  const [isHovered, setIsHovered] = useState(false);
  const [translateX, setTranslateX] = useState(0);
  const [animationDuration, setAnimationDuration] = useState(0);

  useEffect(() => {
    if (effectiveMode !== 'tooltip') return;
    const el = measureRef.current;
    if (!el) return;

    const check = () => setIsOverflown(el.scrollWidth > el.offsetWidth);
    check();

    const observer = new ResizeObserver(check);
    observer.observe(el);
    return () => observer.disconnect();
  }, [effectiveMode]);

  useEffect(() => {
    if (effectiveMode !== 'translate') return;
    const container = containerRef.current;
    const text = textRef.current;
    if (!container || !text) return;

    const compute = () => {
      const overflow = text.scrollWidth - container.offsetWidth;
      if (overflow > 0) {
        setTranslateX(-(overflow + 20));
        setAnimationDuration(overflow / speed);
      } else {
        setTranslateX(0);
        setAnimationDuration(0);
      }
    };
    compute();

    const observer = new ResizeObserver(compute);
    observer.observe(container);
    return () => observer.disconnect();
  }, [effectiveMode, speed, children]);

  // ── Wrap mode ──────────────────────────────────────────────────────────────
  if (effectiveMode === 'wrap') {
    return (
      <div className={cn('wrap-break-word w-full whitespace-normal', className)}>{children}</div>
    );
  }

  // ── Translate mode ─────────────────────────────────────────────────────────
  if (effectiveMode === 'translate') {
    const isTruncated = translateX !== 0;
    return (
      // biome-ignore lint/a11y/noStaticElementInteractions: hover triggers scroll animation only
      <div
        ref={containerRef}
        className={cn('relative w-full overflow-hidden whitespace-nowrap', className)}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
      >
        <span
          ref={textRef}
          className={cn(
            'inline-block transition-transform ease-linear',
            !isHovered && 'w-full truncate'
          )}
          style={{
            transform: isHovered && isTruncated ? `translateX(${translateX}px)` : 'translateX(0)',
            transitionDuration: isHovered && isTruncated ? `${animationDuration}s` : '0.3s',
          }}
        >
          {children}
        </span>
      </div>
    );
  }

  // ── Tooltip mode (default) ─────────────────────────────────────────────────
  //
  // An invisible absolute probe (inset-0, whitespace-nowrap) always fills the
  // container width and reports the true text scrollWidth, giving ResizeObserver
  // a stable DOM node that is never conditionally unmounted.
  return (
    <div className={cn('relative w-full min-w-0', className)}>
      <span
        ref={measureRef}
        className="pointer-events-none absolute inset-0 select-none overflow-hidden whitespace-nowrap"
        style={{ visibility: 'hidden' }}
        aria-hidden="true"
      >
        {children}
      </span>

      {/* Desktop — Tooltip */}
      <div className="hidden sm:block">
        {isOverflown ? (
          <TooltipProvider delayDuration={0}>
            <Tooltip>
              <TooltipTrigger asChild>
                <div className="truncate">{children}</div>
              </TooltipTrigger>
              <TooltipContent>
                <p className={contentClassName}>{children}</p>
              </TooltipContent>
            </Tooltip>
          </TooltipProvider>
        ) : (
          <div className="truncate">{children}</div>
        )}
      </div>

      {/* Mobile — Popover on tap */}
      <div className="sm:hidden">
        {isOverflown ? (
          <Popover>
            <PopoverTrigger>
              <div className="truncate">{children}</div>
            </PopoverTrigger>
            <PopoverContent className={cn('w-fit', contentClassName)}>
              <p>{children}</p>
            </PopoverContent>
          </Popover>
        ) : (
          <div className="truncate">{children}</div>
        )}
      </div>
    </div>
  );
}

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '../../ui/overlays/dialog';
import { Button } from '../../ui/actions/button';
import { LoaderCircle, X, Check, AlertTriangle, Trash2 } from 'lucide-react';
import type React from 'react';
import { useState } from 'react';
import { cn } from '../../../lib/utils';

type Props = {
  id?: string;
  className?: string;
  title?: React.ReactNode;
  description?: React.ReactNode;
  content?: React.ReactNode;
  children?: React.ReactNode;
  onClose: () => void;
  onConfirm?: () => void | Promise<void>;
  showCancel?: boolean;
  cancelText?: React.ReactNode;
  confirmText?: React.ReactNode;
  confirmIcon?: React.ReactNode;
  variant?: 'default' | 'destructive' | 'success' | 'warning';
  hideFooter?: boolean;
  open?: boolean;
  disabled?: boolean;
  loading?: boolean;

  /**
   * @description The size of the dialog. Can be a string for custom sizes.
   * @example 'sm', 'md', 'lg', 'xl', 'fullscreen', '90%', '800px', '60vw'
   */
  size?: 'sm' | 'md' | 'lg' | 'xl' | 'fullscreen' | (string & {});
  extraFooter?: React.ReactNode;
};

export function BaseDialog({
  id,
  className,
  title,
  description,
  content,
  children,
  onClose,
  onConfirm,
  showCancel,
  cancelText,
  confirmText,
  confirmIcon,
  variant,
  hideFooter,
  open = true,
  disabled = false,
  loading,
  size = 'lg',
  extraFooter,
}: Props) {
  const [isLoading, setIsLoading] = useState(false);

  const handleConfirm = async () => {
    try {
      if (disabled || loading) return;
      if (onConfirm) {
        setIsLoading(true);
        await onConfirm();
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  const isCustomSize = !['sm', 'md', 'lg', 'xl'].includes(size);

  const getSizeClasses = () => {
    if (size === 'fullscreen' || isCustomSize) {
      // For fullscreen, we'll use inline styles to override defaults
      return '';
    }

    const widthMap = {
      sm: 'sm:!max-w-sm',
      md: 'sm:!max-w-md',
      lg: 'sm:!max-w-lg',
      xl: 'sm:!max-w-xl',
    };
    return widthMap[size as keyof typeof widthMap];
  };

  const getSizeStyles = (): React.CSSProperties => {
    if (size === 'fullscreen') {
      return {
        width: '100vw',
        height: '100vh',
        maxWidth: '100vw',
        maxHeight: '100vh',
      };
    }

    if (isCustomSize) {
      return {
        width: size,
        maxWidth: size,
        maxHeight: '90vh',
      };
    }

    return {};
  };

  const getConfirmIcon = () => {
    if (isLoading) {
      return <LoaderCircle className="size-4 animate-spin" />;
    }

    if (confirmIcon) return confirmIcon;

    switch (variant) {
      case 'success':
        return <Check className="size-4" />;
      case 'destructive':
        return <Trash2 className="size-4" />;
      case 'warning':
        return <AlertTriangle className="size-4" />;
      default:
        return <Check className="size-4" />;
    }
  };

  const getButtonVariant = () => {
    if (variant === 'destructive') return 'destructive';
    if (variant === 'success') return 'default';
    if (variant === 'warning') return 'default';
    return 'default';
  };

  const getButtonClassName = () => {
    if (variant === 'success') {
      return 'bg-green-600 hover:bg-green-700 text-white shadow-sm hover:shadow-md transition-all dark:bg-green-400 dark:text-green-950 dark:hover:bg-green-500';
    }
    if (variant === 'warning') {
      return 'bg-amber-600 hover:bg-amber-700 text-white shadow-sm hover:shadow-md transition-all dark:bg-amber-400 dark:text-amber-950 dark:hover:bg-amber-500';
    }
    return '';
  };

  return (
    <Dialog key={id} open={open} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className={cn(getSizeClasses(), className ?? '')} style={getSizeStyles()}>
        {title && (
          <DialogHeader>
            <DialogTitle>{title}</DialogTitle>
            {description && <DialogDescription>{description}</DialogDescription>}
          </DialogHeader>
        )}
        {content} {children}
        {!hideFooter && (
          <DialogFooter>
            {extraFooter}

            {showCancel !== false && (
              <Button type="button" variant="outline" onClick={onClose}>
                <X className="size-4" />
                {cancelText ?? 'Cancel'}
              </Button>
            )}
            {onConfirm && (
              <Button
                type="button"
                variant={getButtonVariant()}
                className={getButtonClassName()}
                onClick={handleConfirm}
                disabled={disabled || loading || isLoading}
              >
                {isLoading || loading ? (
                  <LoaderCircle className="size-4 animate-spin" />
                ) : (
                  getConfirmIcon()
                )}
                {confirmText ?? 'Confirm'}
              </Button>
            )}
          </DialogFooter>
        )}
      </DialogContent>
    </Dialog>
  );
}

import {
  Sheet,
  SheetClose,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
} from '../../ui/overlays/sheet';
import { Button } from '../../ui/actions/button';
import type React from 'react';
import { cn } from '../../../lib/utils';
import { useState } from 'react';
import { LoaderCircle, XIcon, Maximize2, Minimize2 } from 'lucide-react';

type Props = {
  id?: string;
  className?: string;
  title?: React.ReactNode;
  description?: React.ReactNode;
  content?: React.ReactNode;
  children?: React.ReactNode;
  onClose: () => void;
  onConfirm?: () => void | Promise<void>;
  showCancel?: boolean;
  cancelText?: React.ReactNode;
  confirmText?: React.ReactNode;
  variant?: 'default' | 'destructive' | 'success' | 'warning';
  hideFooter?: boolean;
  open?: boolean;
  direction?: 'top' | 'bottom' | 'left' | 'right';
  disabled?: boolean;
  loading?: boolean;
  /**
   * @description The size of the drawer. Can be a string for custom sizes.
   * @example 'sm', 'md', 'lg', 'xl', 'fullscreen', '90%', '800px', '60vw'
   */
  size?: 'sm' | 'md' | 'lg' | 'xl' | 'fullscreen' | (string & {});
  showFullscreenToggle?: boolean;
  /**
   * Merged onto the main body wrapper (below the header, above the footer).
   * Use to change overflow (e.g. nested column scrolling) while keeping flex-growth.
   */
  contentContainerClassName?: string;
};

export function BaseDrawer({
  id,
  className,
  title,
  description,
  content,
  children,
  onClose,
  onConfirm,
  showCancel,
  cancelText,
  confirmText,
  variant,
  hideFooter,
  open = true,
  direction = 'right',
  disabled = false,
  loading,
  size = 'lg',
  showFullscreenToggle = true,
  contentContainerClassName,
}: Props) {
  const [isLoading, setIsLoading] = useState(false);
  const [currentSize, setCurrentSize] = useState(size);
  const [previousSize, setPreviousSize] = useState<Exclude<typeof size, 'fullscreen'>>('md');

  const handleConfirm = async () => {
    try {
      if (disabled || loading) return;
      if (onConfirm) {
        setIsLoading(true);
        await onConfirm();
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleToggleFullscreen = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (currentSize === 'fullscreen') {
      setCurrentSize(previousSize);
    } else {
      setPreviousSize(currentSize as Exclude<typeof currentSize, 'fullscreen'>);
      setCurrentSize('fullscreen');
    }
  };

  const isCustomSize = !['sm', 'md', 'lg', 'xl', 'fullscreen'].includes(currentSize);

  const getSizeClasses = () => {
    if (currentSize === 'fullscreen' || isCustomSize) {
      return '';
    }

    const isHorizontal = direction === 'left' || direction === 'right';

    if (isHorizontal) {
      const widthMap = {
        sm: 'sm:!max-w-sm',
        md: 'sm:!max-w-md',
        lg: 'sm:!max-w-lg',
        xl: 'sm:!max-w-xl',
      };
      return widthMap[currentSize as keyof typeof widthMap];
    }

    const heightMap = {
      sm: '!max-h-[50vh]',
      md: '!max-h-[70vh]',
      lg: '!max-h-[80vh]',
      xl: '!max-h-[90vh]',
    };
    return heightMap[currentSize as keyof typeof heightMap];
  };

  const getSizeStyles = (): React.CSSProperties => {
    if (currentSize === 'fullscreen') {
      const isHorizontal = direction === 'left' || direction === 'right';
      if (isHorizontal) {
        return { width: '100%', maxWidth: '100%' };
      }
      return { maxHeight: '100vh', height: '100vh' };
    }

    if (isCustomSize) {
      const isHorizontal = direction === 'left' || direction === 'right';
      if (isHorizontal) {
        return { width: currentSize, maxWidth: currentSize };
      }
      return { height: currentSize, maxHeight: currentSize };
    }

    return {};
  };

  return (
    <Sheet key={id} open={open} onOpenChange={(isOpen) => !isOpen && onClose()}>
      <SheetContent
        side={direction}
        showCloseButton={false}
        className={cn('flex flex-col gap-0', getSizeClasses(), className)}
        style={getSizeStyles()}
      >
        {title && (
          <SheetHeader className="flex flex-row items-center justify-between">
            <SheetTitle>{title}</SheetTitle>
            <div className="flex items-center gap-2">
              {showFullscreenToggle && (
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={handleToggleFullscreen}
                  disabled={loading}
                  aria-label={currentSize === 'fullscreen' ? 'Exit fullscreen' : 'Enter fullscreen'}
                >
                  {currentSize === 'fullscreen' ? <Minimize2 size={16} /> : <Maximize2 size={16} />}
                </Button>
              )}
              <SheetClose
                render={
                  <Button variant="ghost" size="icon" disabled={loading}>
                    <XIcon size={20} />
                  </Button>
                }
              />
            </div>
          </SheetHeader>
        )}
        <div
          className={cn(
            'flex min-h-0 flex-1 flex-col overflow-y-auto px-4 pb-9',
            contentContainerClassName
          )}
        >
          {description && <SheetDescription render={<div />}>{description}</SheetDescription>}
          {content}
          {children}
        </div>
        {!hideFooter && (
          <SheetFooter className="mt-auto flex flex-row items-center justify-end gap-2 border-t bg-background">
            {showCancel !== false && (
              <SheetClose
                render={
                  <Button variant="ghost" disabled={loading}>
                    {cancelText ?? 'Close'}
                  </Button>
                }
              />
            )}
            {onConfirm && (
              <Button
                variant={variant === 'destructive' ? 'destructive' : 'default'}
                onClick={handleConfirm}
                disabled={disabled || loading}
              >
                {isLoading && <LoaderCircle className="size-4 animate-spin" />}
                {confirmText ?? 'Confirm'}
              </Button>
            )}
          </SheetFooter>
        )}
      </SheetContent>
    </Sheet>
  );
}

import {
