  title?: React.ReactNode;
  description?: string | React.ReactNode;
  content?: React.ReactNode;
  onClose?: () => void;
  onConfirm?: () => void | Promise<void>;
  showCancel?: boolean;
  cancelText?: React.ReactNode;
  confirmText?: React.ReactNode;
  variant?: 'default' | 'destructive' | 'success' | 'warning';
  hideFooter?: boolean;
  open?: boolean;
  disabled?: boolean;
  loading?: boolean;
  children?: React.ReactNode;
  /**
   * @deprecated Use onClose instead
   */
  onOpenChange?: (open: boolean) => void;
};

export function ConfirmDialog({
  id,
  className,
  title,
  description,
  content,
  onClose,
  onConfirm,
  showCancel,
  cancelText,
  confirmText,
  variant,
  hideFooter,
  open = true,
  disabled = false,
  loading,
  children,
  onOpenChange,
}: ConfirmDialogProps) {
  const [isLoading, setIsLoading] = useState(false);

  const handleConfirm = async () => {
    try {
      if (disabled || loading) return;
      if (onConfirm) {
        setIsLoading(true);
        await onConfirm();
      }
      onClose?.();
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <AlertDialog
      key={id}
      open={open}
      onOpenChange={(open) => {
        if (onOpenChange) {
          onOpenChange(open);
        } else {
          !open && onClose?.();
        }
      }}
    >
      <AlertDialogContent className={cn(className ?? '')}>
        {title && (
          <AlertDialogHeader className="text-start">
            <AlertDialogTitle>{title}</AlertDialogTitle>
            {description && (
              <AlertDialogDescription asChild>
                <div>{description}</div>
              </AlertDialogDescription>
            )}
          </AlertDialogHeader>
        )}
        {content}
        {children}
        {!hideFooter && (
          <AlertDialogFooter>
            {showCancel !== false && (
              <AlertDialogCancel disabled={loading} onClick={onClose}>
                {cancelText ?? 'Cancel'}
              </AlertDialogCancel>
            )}
            {onConfirm && (
              <Button
                variant={variant === 'destructive' ? 'destructive' : 'default'}
                onClick={handleConfirm}
                disabled={disabled || loading}
              >
                {isLoading && <LoaderCircle className="size-4 animate-spin" />}
                {confirmText ?? 'Confirm'}
              </Button>
            )}
          </AlertDialogFooter>
        )}
      </AlertDialogContent>
    </AlertDialog>
  );
}

import { ConfirmDialog } from './confirm-dialog';
import { BaseDialog } from './base-dialog';
import { BaseDrawer } from './base-drawer';
import { useModals } from '../../../context/modal-provider/useModals';

export function GlobalModal() {
  const { modals, closeModal } = useModals();

  return (
    <>
      {Object.entries(modals).map(([id, config]) => {
        const handleClose = () => {
          config.onClose?.();
          closeModal(id);
        };

        const handleConfirm = async () => {
          if (config.onConfirm) {
            await config.onConfirm();
          }
          closeModal(id);
        };

        if (config.type === 'confirm') {
          return (
            <ConfirmDialog
              key={id}
              id={id}
              open={true}
              onClose={handleClose}
              onConfirm={handleConfirm}
              title={config.title}
              description={config.description}
              content={config.content}
              confirmText={config.confirmText}
              cancelText={config.cancelText}
              variant={config.variant}
              className={config.className}
              showCancel={config.showCancel}
            />
          );
        }

        if (config.type === 'custom') {
          const Component = config.component;
          return (
            <Component
              key={id}
              {...config.componentProps}
              onClose={handleClose}
              onConfirm={config.onConfirm ? handleConfirm : undefined}
            />
          );
        }

        // inner-content type
        const isDrawer = config.style === 'drawer';
        const direction = config.direction ?? 'right';

        if (config.type === 'inner-content') {
          if (isDrawer) {
            return (
              <BaseDrawer
                key={id}
                id={id}
                className={config.className}
                title={config.title}
                description={config.description}
                content={config.content}
                onClose={handleClose}
                onConfirm={config.onConfirm ? handleConfirm : undefined}
                showCancel={config.showCancel}
                cancelText={config.cancelText}
                confirmText={config.confirmText}
                variant={config.variant}
                open={true}
                direction={direction}
              />
            );
          }

          return (
            <BaseDialog
              key={id}
              id={id}
              className={config.className}
              title={config.title}
              description={config.description}
              content={config.content}
              onClose={handleClose}
              onConfirm={config.onConfirm ? handleConfirm : undefined}
              showCancel={config.showCancel}
              cancelText={config.cancelText}
              confirmText={config.confirmText}
              variant={config.variant}
              open={true}
            />
          );
        }

        return null;
      })}
    </>
  );
}

