import type * as React from 'react';
import type { DateValue, DateRange } from '../../../../features/date-picker/types';

export type { DateValue, DateRange };

export type CalendarMode = 'year' | 'month' | 'week' | 'day';
export type CalendarSelectionType = 'range' | 'multiple' | 'single';

export type CalendarPreset = {
  value: string; // YYYY-MM-DD date string
  label: string;
};

export type CalendarValueMap = {
  single: DateValue;
  multiple: DateValue[];
  range: DateRange;
};

export type InternalView = 'primary' | 'month-grid' | 'year-grid';

export type CalendarProps<T extends CalendarSelectionType = 'single'> = {
  mode?: CalendarMode;
  type?: T;
  value?: CalendarValueMap[T];
  onChange?: (value: CalendarValueMap[T]) => void;
  minDate?: Date;
  maxDate?: Date;
  disabled?: boolean;
  readOnly?: boolean;
  className?: string;
  style?: React.CSSProperties;
  onFocus?: () => void;
  onBlur?: () => void;
  locale?: string;
  renderActions?: () => React.ReactNode;
  presets?: CalendarPreset[];
};

export type ViewSharedProps = {
  navDate: Date;
  onNavDateChange: (date: Date) => void;
  onDrillUp?: () => void;
  minDate?: Date;
  maxDate?: Date;
  disabled?: boolean;
  readOnly?: boolean;
  locale?: string;
};

import {
  endOfWeek,
  startOfMonth,
  endOfMonth,
  startOfWeek,
  addWeeks,
  getWeek,
  parse,
} from 'date-fns';

export {
  toUTCDate,
  toDateOrUndefined,
  parseUTCString,
  formatDateToUTCString,
} from '../../../../features/date-picker/utils';

/** Floor year to the start of its decade (e.g. 2026 → 2020) */
export function getDecadeStart(year: number): number {
  return Math.floor(year / 10) * 10;
}

/** Return array of 10 years for the given decade start */
export function getDecadeYears(decadeStart: number): number[] {
  return Array.from({ length: 10 }, (_, i) => decadeStart + i);
}

/** Parse a YYYY-MM-DD preset string to a local Date */
export function parsePresetValue(value: string): Date {
  return parse(value, 'yyyy-MM-dd', new Date());
}

/** Format a Date to YYYY-MM-DD string for comparison with preset values */
export function formatToPresetValue(date: Date): string {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

export type WeekEntry = {
  weekNumber: number;
  start: Date;
  end: Date;
};

/** Get all weeks that overlap with a given month */
export function getWeeksInMonth(
  year: number,
  month: number,
  weekStartsOn: 0 | 1 | 2 | 3 | 4 | 5 | 6 = 1
): WeekEntry[] {
  const monthStart = startOfMonth(new Date(year, month, 1));
  const monthEnd = endOfMonth(monthStart);

  const weeks: WeekEntry[] = [];
  let current = startOfWeek(monthStart, { weekStartsOn });

  while (current <= monthEnd) {
    const weekEnd = endOfWeek(current, { weekStartsOn });
    const weekContainsMonthDay =
      (current >= monthStart && current <= monthEnd) ||
      (weekEnd >= monthStart && weekEnd <= monthEnd) ||
      (current <= monthStart && weekEnd >= monthEnd);

    if (weekContainsMonthDay) {
      weeks.push({
        weekNumber: getWeek(current, { weekStartsOn, firstWeekContainsDate: 4 }),
        start: current,
        end: weekEnd,
      });
    }

    current = addWeeks(current, 1);
  }

  return weeks;
}

/** Check if two dates represent the same week start */
export function isSameWeekStart(a: Date, b: Date): boolean {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

/** Check if a year-month is between two year-months (inclusive) */
export function isMonthInRange(
  year: number,
  month: number,
  fromYear?: number,
  fromMonth?: number,
  toYear?: number,
  toMonth?: number
): boolean {
  if (fromYear == null || fromMonth == null || toYear == null || toMonth == null) return false;
  const val = year * 12 + month;
  const from = fromYear * 12 + fromMonth;
  const to = toYear * 12 + toMonth;
  return val >= Math.min(from, to) && val <= Math.max(from, to);
}

/** Check if a year is between two years (inclusive) */
export function isYearInRange(year: number, fromYear?: number, toYear?: number): boolean {
  if (fromYear == null || toYear == null) return false;
  return year >= Math.min(fromYear, toYear) && year <= Math.max(fromYear, toYear);
}

/**
 * DayView — custom day calendar built directly on react-day-picker v9.
 *
 * Key design decisions:
 * - Does NOT wrap Calendar v1 so we have full control over component overrides.
 * - Uses a React context to pass `onDrillUp` into the stable `CaptionLabel`
 *   override, avoiding the remount issue caused by inline component definitions.
 * - Range type renders two isolated panels: left picks `from`, right picks `to`.
 *   Each panel navigates independently and shares range-highlight modifiers.
 */

import * as React from 'react';
import {
  DayPicker,
  getDefaultClassNames,
  type DayButton,
  type CaptionLabelProps,
} from 'react-day-picker';
import { addMonths } from 'date-fns'; // used for fallback rightNavDate only
import { ChevronLeftIcon, ChevronRightIcon } from 'lucide-react';
import { Button, buttonVariants } from '../../../../actions/button';
import { cn } from '../../../../../../lib/utils';
import { toDateOrUndefined } from '../utils';
import type { CalendarSelectionType, DateValue, DateRange, ViewSharedProps } from '../types';

// ─────────────────────────────────────────────────────────────
// Context — lets the stable CaptionLabel access onDrillUp
// ─────────────────────────────────────────────────────────────

const DrillUpContext = React.createContext<(() => void) | undefined>(undefined);

// ─────────────────────────────────────────────────────────────
// Stable component overrides (defined outside — never remounted)
// ─────────────────────────────────────────────────────────────

const defaultClassNames = getDefaultClassNames();

/** Replaces the plain <span> with a clickable button that triggers drill-up. */
function DrillableCaptionLabel({ children, ...props }: CaptionLabelProps) {
  const onDrillUp = React.useContext(DrillUpContext);
  return (
    <button
      type="button"
      onClick={onDrillUp}
      className={cn(
        'select-none rounded px-1 font-medium text-sm',
        onDrillUp && 'cursor-pointer hover:bg-accent hover:text-accent-foreground',
        !onDrillUp && 'cursor-default'
      )}
      {...props}
    >
      {children}
    </button>
  );
}

/** Chevron used for prev/next navigation buttons. */
function DayViewChevron({
  orientation,
  className,
}: {
  orientation?: 'left' | 'right' | 'up' | 'down';
  className?: string;
}) {
  if (orientation === 'left') return <ChevronLeftIcon className={cn('size-4', className)} />;
  return <ChevronRightIcon className={cn('size-4', className)} />;
}

/** Day button with selection/range highlighting — mirrors Calendar v1 styling. */
function DayViewDayButton({
  className,
  day,
  modifiers,
  ...props
}: React.ComponentProps<typeof DayButton>) {
  const focusRef = (el: HTMLButtonElement | null) => {
    if (modifiers.focused && el) el.focus();
  };

  return (
    <Button
      ref={focusRef}
      variant="ghost"
      size="icon"
      data-day={day.date.toLocaleDateString()}
      data-selected-single={
        modifiers.selected &&
        !modifiers.range_start &&
        !modifiers.range_end &&
        !modifiers.range_middle
      }
      data-range-start={modifiers.range_start}
      data-range-end={modifiers.range_end}
      data-range-middle={modifiers.range_middle}
      className={cn(
        'flex aspect-square size-auto w-full min-w-(--cell-size) flex-col gap-1 font-normal leading-none',
        'data-[range-end=true]:rounded-md data-[range-middle=true]:rounded-none data-[range-start=true]:rounded-md',
        'data-[range-end=true]:rounded-r-md data-[range-start=true]:rounded-l-md',
        'data-[range-end=true]:bg-primary data-[range-middle=true]:bg-accent data-[range-start=true]:bg-primary data-[selected-single=true]:bg-primary',
        'data-[range-end=true]:text-primary-foreground data-[range-middle=true]:text-accent-foreground data-[range-start=true]:text-primary-foreground data-[selected-single=true]:text-primary-foreground',
        'group-data-[focused=true]/day:relative group-data-[focused=true]/day:z-10 group-data-[focused=true]/day:border-ring group-data-[focused=true]/day:ring-[3px] group-data-[focused=true]/day:ring-ring/50',
        'dark:hover:text-accent-foreground [&>span]:text-xs [&>span]:opacity-70',
        defaultClassNames.day,
        className
      )}
      {...props}
    />
  );
}

