const DAY_PICKER_COMPONENTS = {
  CaptionLabel: DrillableCaptionLabel,
  Chevron: DayViewChevron,
  DayButton: DayViewDayButton,
} as const;

// ─────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────

type DayViewProps = ViewSharedProps & {
  selectionType: CalendarSelectionType;
  value?: DateValue | DateValue[] | DateRange;
  onChange?: (value: DateValue | DateValue[] | DateRange) => void;
  // range day-mode only — lifted to CalendarV2 for drill-up routing
  rightNavDate?: Date;
  onRightNavDateChange?: (date: Date) => void;
  onDrillUpRight?: () => void;
};

function toDateArray(value?: DateValue[]): Date[] | undefined {
  if (!value) return undefined;
  const dates = value.map((v) => toDateOrUndefined(v)).filter((d): d is Date => d != null);
  return dates.length > 0 ? dates : undefined;
}

function isSameDate(a: Date, b: Date): boolean {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

/** Build the disabled matcher — avoids passing `disabled: []` to DayPicker. */
function buildDisabled(
  isDisabled?: boolean,
  minDate?: Date,
  maxDate?: Date
): true | Array<{ before: Date } | { after: Date }> | undefined {
  if (isDisabled) return true;
  const matchers: Array<{ before: Date } | { after: Date }> = [
    ...(minDate ? [{ before: minDate }] : []),
    ...(maxDate ? [{ after: maxDate }] : []),
  ];
  return matchers.length > 0 ? matchers : undefined;
}

// ─────────────────────────────────────────────────────────────
// DayView
// ─────────────────────────────────────────────────────────────

export function DayView({
  navDate,
  onNavDateChange,
  onDrillUp,
  selectionType,
  value,
  onChange,
  minDate,
  maxDate,
  disabled,
  readOnly,
  rightNavDate: rightNavDateProp,
  onRightNavDateChange,
  onDrillUpRight,
}: DayViewProps) {
  const effectiveOnChange = readOnly ? undefined : onChange;
  const disabledMatcher = buildDisabled(disabled, minDate, maxDate);

  // Fallback right-panel nav when CalendarV2 doesn't supply it (standalone use).
  const [fallbackRightNavDate, setFallbackRightNavDate] = React.useState<Date>(() =>
    addMonths(navDate, 1)
  );
  const rightNavDate = rightNavDateProp ?? fallbackRightNavDate;
  const setRightNavDate = onRightNavDateChange ?? setFallbackRightNavDate;

  const sharedDayPickerProps = {
    showOutsideDays: true,
    className: cn(
      'group/calendar bg-background p-3 [--cell-size:--spacing(7)]',
      String.raw`rtl:**:[.rdp-button\_next>svg]:rotate-180`,
      String.raw`rtl:**:[.rdp-button\_previous>svg]:rotate-180`
    ),
    classNames: DAY_PICKER_CLASS_NAMES,
    components: DAY_PICKER_COMPONENTS,
    ...(disabledMatcher !== undefined ? { disabled: disabledMatcher } : {}),
  };

  const commonProps = {
    ...sharedDayPickerProps,
    month: navDate,
    onMonthChange: onNavDateChange,
  } as const;

  if (selectionType === 'single') {
    const selected = toDateOrUndefined(value as DateValue);

    const handleSelect = (date?: Date) => {
      if (!date) {
        effectiveOnChange?.(undefined);
        return;
      }
      // Click again to deselect
      if (selected && isSameDate(date, selected)) {
        effectiveOnChange?.(undefined);
        return;
      }
      effectiveOnChange?.(date);
    };

    return (
      <DrillUpContext.Provider value={onDrillUp}>
        <DayPicker mode="single" selected={selected} onSelect={handleSelect} {...commonProps} />
      </DrillUpContext.Provider>
    );
  }

  if (selectionType === 'multiple') {
    const selected = toDateArray(value as DateValue[] | undefined);

    const handleSelect = (dates?: Date[]) => {
      effectiveOnChange?.(dates ?? []);
    };

    return (
      <DrillUpContext.Provider value={onDrillUp}>
        <DayPicker mode="multiple" selected={selected} onSelect={handleSelect} {...commonProps} />
      </DrillUpContext.Provider>
    );
  }

  // ── Range: two isolated panels ────────────────────────────
  // Left panel picks `from`, right panel picks `to`.
  // Each navigates independently; both share range-highlight modifiers.
  const rangeValue = value as DateRange | undefined;
  const from = toDateOrUndefined(rangeValue?.from);
  const to = toDateOrUndefined(rangeValue?.to);

  // Right panel must disable all dates before `from` (end >= start constraint).
  // Use the later of `from` and `minDate` as the effective lower bound.
  const rightEffectiveMin =
    from != null && minDate != null
      ? from.getTime() > minDate.getTime()
        ? from
        : minDate
      : (from ?? minDate);
  const rightDisabledMatcher = buildDisabled(disabled, rightEffectiveMin, maxDate);

  const rangeModifiers = {
    range_start: from ? [from] : [],
    range_end: to ? [to] : [],
    range_middle:
      from != null && to != null && from.getTime() <= to.getTime()
        ? { after: from, before: to }
        : [],
  };

  const handleFromSelect = (date?: Date) => {
    if (!date) {
      effectiveOnChange?.({ from: undefined, to: rangeValue?.to });
      return;
    }
    if (from && isSameDate(date, from)) {
      effectiveOnChange?.({ from: undefined, to: rangeValue?.to });
      return;
    }
    // Clear `to` when the new `from` would make it an invalid range.
    const existingTo = toDateOrUndefined(rangeValue?.to);
    const newTo =
      existingTo != null && existingTo.getTime() >= date.getTime() ? rangeValue?.to : undefined;
    effectiveOnChange?.({ from: date, to: newTo });
  };

  const handleToSelect = (date?: Date) => {
    if (!date) {
      effectiveOnChange?.({ from: rangeValue?.from, to: undefined });
      return;
    }
    if (to && isSameDate(date, to)) {
      effectiveOnChange?.({ from: rangeValue?.from, to: undefined });
      return;
    }
    effectiveOnChange?.({ from: rangeValue?.from, to: date });
  };

  return (
    <div className="flex divide-x">
      {/* Left panel — picks `from`. Drill-up routes to left nav. */}
      <DrillUpContext.Provider value={onDrillUp}>
        <DayPicker
          mode="single"
          selected={from}
          onSelect={handleFromSelect}
          modifiers={rangeModifiers}
          {...sharedDayPickerProps}
          month={navDate}
          onMonthChange={onNavDateChange}
        />
      </DrillUpContext.Provider>
      {/* Right panel — picks `to`. Drill-up routes to right nav. */}
      <DrillUpContext.Provider value={onDrillUpRight}>
        <DayPicker
          mode="single"
          selected={to}
          onSelect={handleToSelect}
          modifiers={rangeModifiers}
          {...sharedDayPickerProps}
          month={rightNavDate}
          onMonthChange={setRightNavDate}
          {...(rightDisabledMatcher !== undefined ? { disabled: rightDisabledMatcher } : {})}
        />
      </DrillUpContext.Provider>
    </div>
  );
}

DayView.displayName = 'DayView';

import { cn } from '../../../../../../lib/utils';
import { toDateOrUndefined, isMonthInRange } from '../utils';
import { ViewHeader } from '../components/ViewHeader';
import type { CalendarSelectionType, DateValue, DateRange, ViewSharedProps } from '../types';

const NOW = new Date();
const TODAY_YEAR = NOW.getFullYear();
const TODAY_MONTH = NOW.getMonth();

type MonthGridViewProps = ViewSharedProps & {
  selectionType: CalendarSelectionType;
  value?: DateValue | DateValue[] | DateRange;
  onChange?: (value: DateValue | DateValue[] | DateRange) => void;
  /** Called when the year label is clicked to drill up to year selection. */
  onDrillUp?: () => void;
  /** Called after a month is committed (for drill-back to primary view). */
  onMonthSelect?: (date: Date) => void;
};

const MONTHS: { number: number; name: string }[][] = [
  [
    { number: 0, name: 'Jan' },
    { number: 1, name: 'Feb' },
    { number: 2, name: 'Mar' },
  ],
  [
    { number: 3, name: 'Apr' },
    { number: 4, name: 'May' },
    { number: 5, name: 'Jun' },
  ],
  [
    { number: 6, name: 'Jul' },
    { number: 7, name: 'Aug' },
    { number: 8, name: 'Sep' },
  ],
  [
    { number: 9, name: 'Oct' },
    { number: 10, name: 'Nov' },
    { number: 11, name: 'Dec' },
  ],
];

function getSelectedMonths(
  selectionType: CalendarSelectionType,
  value?: DateValue | DateValue[] | DateRange
): Array<{ year: number; month: number }> {
  if (selectionType === 'range') {
    const range = value as DateRange | undefined;
    const result: Array<{ year: number; month: number }> = [];
    const from = toDateOrUndefined(range?.from);
    const to = toDateOrUndefined(range?.to);
    if (from) result.push({ year: from.getFullYear(), month: from.getMonth() });
    if (to) result.push({ year: to.getFullYear(), month: to.getMonth() });
    return result;
  }
  if (selectionType === 'multiple') {
    const dates = (value as DateValue[] | undefined) ?? [];
    return dates
      .map((d) => toDateOrUndefined(d))
      .filter((d): d is Date => d != null)
      .map((d) => ({ year: d.getFullYear(), month: d.getMonth() }));
  }
  const single = toDateOrUndefined(value as DateValue);
  return single ? [{ year: single.getFullYear(), month: single.getMonth() }] : [];
}

function getRangeMonths(value?: DateValue | DateValue[] | DateRange) {
  const range = value as DateRange | undefined;
  const from = toDateOrUndefined(range?.from);
  const to = toDateOrUndefined(range?.to);
  return {
    fromYear: from?.getFullYear(),
    fromMonth: from?.getMonth(),
    toYear: to?.getFullYear(),
    toMonth: to?.getMonth(),
  };
}

export function MonthGridView({
  navDate,
  onNavDateChange,
  selectionType,
  value,
  onChange,
  onDrillUp,
  onMonthSelect,
  minDate,
  maxDate,
  disabled,
  readOnly,
}: MonthGridViewProps) {
  const year = navDate.getFullYear();
  const selectedMonths = getSelectedMonths(selectionType, value);
  const { fromYear, fromMonth, toYear, toMonth } =
    selectionType === 'range' ? getRangeMonths(value) : {};

  const isMonthDisabled = (monthNum: number) => {
    if (maxDate) {
      if (year > maxDate.getFullYear()) return true;
      if (year === maxDate.getFullYear() && monthNum > maxDate.getMonth()) return true;
    }
    if (minDate) {
      if (year < minDate.getFullYear()) return true;
      if (year === minDate.getFullYear() && monthNum < minDate.getMonth()) return true;
    }
    return false;
  };

  const handleMonthClick = (monthNum: number) => {
    if (disabled || readOnly || isMonthDisabled(monthNum)) return;
    const date = new Date(year, monthNum, 1);

    // Navigation-only mode (no onChange): treat any click as navigation
    if (!onChange) {
      onMonthSelect?.(date);
      return;
    }

    if (selectionType === 'single') {
      const current = toDateOrUndefined(value as DateValue);
      const isSame = current?.getFullYear() === year && current?.getMonth() === monthNum;
      onChange?.(isSame ? undefined : date);
      if (!isSame) onMonthSelect?.(date);
    } else if (selectionType === 'multiple') {
      const current = (value as DateValue[] | undefined) ?? [];
      const idx = current.findIndex((d) => {
        const p = toDateOrUndefined(d);
        return p?.getFullYear() === year && p?.getMonth() === monthNum;
      });
      onChange?.(idx >= 0 ? current.filter((_, i) => i !== idx) : [...current, date]);
    } else {
      const range = (value as DateRange | undefined) ?? { from: undefined, to: undefined };
      const from = toDateOrUndefined(range.from);
      const to = toDateOrUndefined(range.to);
      if (!from || (from && to)) {
        onChange?.({ from: date, to: undefined });
      } else {
        onChange?.({ from: date < from ? date : from, to: date < from ? from : date });
        onMonthSelect?.(date);
      }
    }
  };

  return (
    <div className="w-full p-3">
      <ViewHeader
        title={year}
        onPrev={() => onNavDateChange(new Date(year - 1, navDate.getMonth(), 1))}
        onNext={() => onNavDateChange(new Date(year + 1, navDate.getMonth(), 1))}
        onTitleClick={onDrillUp}
        prevLabel="Previous year"
        nextLabel="Next year"
      />

      <div className="mt-3 flex flex-col gap-1">
        {MONTHS.map((row, rowIdx) => (
          <div key={`row-${rowIdx}`} className="flex gap-1">
            {row.map((month) => {
              const isSelected = selectedMonths.some(
                (s) => s.year === year && s.month === month.number
              );
              const isToday = year === TODAY_YEAR && month.number === TODAY_MONTH;
              const isInRange =
                selectionType === 'range' &&
                isMonthInRange(year, month.number, fromYear, fromMonth, toYear, toMonth);
              const isRangeStart =
                selectionType === 'range' && year === fromYear && month.number === fromMonth;
              const isRangeEnd =
                selectionType === 'range' && year === toYear && month.number === toMonth;
              const isEndpoint = isRangeStart || isRangeEnd;
              const isDisabled = isMonthDisabled(month.number);

              return (
                <button
                  key={month.number}
                  type="button"
                  onClick={() => handleMonthClick(month.number)}
                  disabled={isDisabled || disabled}
                  className={cn(
                    'relative flex h-9 flex-1 items-center justify-center rounded-md font-normal text-sm transition-colors',
                    'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1',
                    'disabled:pointer-events-none disabled:opacity-40',
                    isInRange && !isEndpoint && 'rounded-none bg-accent text-accent-foreground',
                    isRangeStart && 'rounded-r-none',
                    isRangeEnd && 'rounded-l-none',
                    isSelected
                      ? 'bg-primary text-primary-foreground hover:bg-primary/90'
                      : isInRange && !isEndpoint
                        ? 'hover:bg-accent/80'
                        : 'hover:bg-accent hover:text-accent-foreground',
                    isToday && !isSelected && 'font-semibold text-primary'
                  )}
                >
                  {month.name}
                  {isToday && !isSelected && (
                    <span className="absolute bottom-1 left-1/2 size-1 -translate-x-1/2 rounded-full bg-primary" />
                  )}
                </button>
              );
            })}
          </div>
        ))}
      </div>
    </div>
  );
}

MonthGridView.displayName = 'MonthGridView';

import {
  format,
  addMonths,
  subMonths,
  endOfWeek,
  isBefore,
  isAfter,
  isSameDay,
  startOfWeek,
  isWithinInterval,
} from 'date-fns';
import { cn } from '../../../../../../lib/utils';
import { toDateOrUndefined, getWeeksInMonth, isSameWeekStart } from '../utils';
import { ViewHeader } from '../components/ViewHeader';
import type { CalendarSelectionType, DateValue, DateRange, ViewSharedProps } from '../types';

const WEEK_STARTS_ON: 0 | 1 = 1; // Monday

type WeekViewProps = ViewSharedProps & {
  selectionType: CalendarSelectionType;
  value?: DateValue | DateValue[] | DateRange;
  onChange?: (value: DateValue | DateValue[] | DateRange) => void;
};

function getSelectedWeekStarts(
  selectionType: CalendarSelectionType,
  value?: DateValue | DateValue[] | DateRange
): Date[] {
  if (selectionType === 'range') {
    const range = value as DateRange | undefined;
    const results: Date[] = [];
    const from = toDateOrUndefined(range?.from);
    const to = toDateOrUndefined(range?.to);
    if (from) results.push(startOfWeek(from, { weekStartsOn: WEEK_STARTS_ON }));
    if (to) results.push(startOfWeek(to, { weekStartsOn: WEEK_STARTS_ON }));
    return results;
  }
  if (selectionType === 'multiple') {
    const dates = (value as DateValue[] | undefined) ?? [];
    return dates
      .map((d) => toDateOrUndefined(d))
      .filter((d): d is Date => d != null)
      .map((d) => startOfWeek(d, { weekStartsOn: WEEK_STARTS_ON }));
  }
  const single = toDateOrUndefined(value as DateValue);
  return single ? [startOfWeek(single, { weekStartsOn: WEEK_STARTS_ON })] : [];
}

export function WeekView({
  navDate,
  onNavDateChange,
  onDrillUp,
  selectionType,
  value,
  onChange,
  minDate,
  maxDate,
  disabled,
  readOnly,
}: WeekViewProps) {
  const weeks = getWeeksInMonth(navDate.getFullYear(), navDate.getMonth(), WEEK_STARTS_ON);
  const selectedStarts = getSelectedWeekStarts(selectionType, value);

  const rangeFrom =
    selectionType === 'range'
      ? toDateOrUndefined((value as DateRange | undefined)?.from)
      : undefined;
  const rangeTo =
    selectionType === 'range' ? toDateOrUndefined((value as DateRange | undefined)?.to) : undefined;

  const today = new Date();
  const todayWeekStart = startOfWeek(today, { weekStartsOn: WEEK_STARTS_ON });

  const isWeekDisabled = (start: Date, end: Date) => {
    if (minDate && isBefore(end, minDate)) return true;
    if (maxDate && isAfter(start, maxDate)) return true;
    return false;
  };

  const isWeekSelected = (start: Date) => selectedStarts.some((s) => isSameWeekStart(s, start));

  const isWeekInRange = (start: Date, end: Date) => {
    if (!rangeFrom || !rangeTo) return false;
    return !isBefore(end, rangeFrom) && !isAfter(start, rangeTo);
  };

  const isRangeEndpoint = (start: Date) => {
    if (!rangeFrom || !rangeTo) return false;
    return (
      isSameDay(start, startOfWeek(rangeFrom, { weekStartsOn: WEEK_STARTS_ON })) ||
      isSameDay(start, startOfWeek(rangeTo, { weekStartsOn: WEEK_STARTS_ON }))
    );
  };

  const isTodayWeek = (start: Date) => isSameDay(start, todayWeekStart);

  const isCurrentMonth = (start: Date, end: Date) =>
    isWithinInterval(today, { start, end }) ||
    (start.getMonth() === today.getMonth() && start.getFullYear() === today.getFullYear());

  const handleWeekClick = (start: Date, end: Date) => {
    if (disabled || readOnly || isWeekDisabled(start, end)) return;

    if (selectionType === 'single') {
      onChange?.(isWeekSelected(start) ? undefined : start);
    } else if (selectionType === 'multiple') {
      const current = (value as DateValue[] | undefined) ?? [];
      if (isWeekSelected(start)) {
        onChange?.(
          current.filter((d) => {
            const parsed = toDateOrUndefined(d);
            if (!parsed) return true;
            return !isSameWeekStart(startOfWeek(parsed, { weekStartsOn: WEEK_STARTS_ON }), start);
          })
        );
      } else {
        onChange?.([...current, start]);
      }
    } else {
      const range = (value as DateRange | undefined) ?? { from: undefined, to: undefined };
      const from = toDateOrUndefined(range.from);
      const to = toDateOrUndefined(range.to);
      if (!from || (from && to)) {
        onChange?.({ from: start, to: undefined });
      } else {
        const rangeStart = start < from ? start : from;
        const rangeEnd = start < from ? from : start;
        onChange?.({ from: rangeStart, to: endOfWeek(rangeEnd, { weekStartsOn: WEEK_STARTS_ON }) });
      }
    }
  };

  return (
    <div className="w-full p-3">
      <ViewHeader
        title={format(navDate, 'MMMM yyyy')}
        onPrev={() => onNavDateChange(subMonths(navDate, 1))}
        onNext={() => onNavDateChange(addMonths(navDate, 1))}
        onTitleClick={onDrillUp}
        prevLabel="Previous month"
        nextLabel="Next month"
      />

      <div className="mt-3 flex flex-col gap-1">
        {weeks.map(({ weekNumber, start, end }) => {
          const isDisabled = isWeekDisabled(start, end);
          const selected = isWeekSelected(start);
          const inRange = selectionType === 'range' && isWeekInRange(start, end);
          const endpoint = selectionType === 'range' && isRangeEndpoint(start);
          const isToday = isTodayWeek(start);
          const isCurrent = isCurrentMonth(start, end);

          return (
            <button
              key={start.toISOString()}
              type="button"
              disabled={isDisabled || disabled}
              onClick={() => handleWeekClick(start, end)}
              className={cn(
                'flex h-9 w-full items-center justify-between rounded-md px-3 text-sm transition-colors',
                'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1',
                'disabled:pointer-events-none disabled:opacity-40',
                selected || endpoint
                  ? 'bg-primary text-primary-foreground hover:bg-primary/90'
                  : inRange
                    ? 'bg-accent text-accent-foreground hover:bg-accent/80'
                    : 'hover:bg-accent hover:text-accent-foreground'
              )}
            >
              <span
                className={cn(
                  'w-8 shrink-0 text-left text-xs tabular-nums',
                  selected || endpoint ? 'text-primary-foreground/70' : 'text-muted-foreground',
                  isToday && !selected && !endpoint && 'font-semibold text-primary'
                )}
              >
                W{weekNumber}
              </span>
              <span
                className={cn(
                  'font-medium',
                  !isCurrent && !selected && !endpoint && 'text-muted-foreground'
                )}
              >
                {format(start, 'MMM d')} – {format(end, 'MMM d')}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

WeekView.displayName = 'WeekView';

import { cn } from '../../../../../../lib/utils';
import { toDateOrUndefined, getDecadeStart, getDecadeYears, isYearInRange } from '../utils';
import { ViewHeader } from '../components/ViewHeader';
import type { CalendarSelectionType, DateValue, DateRange, ViewSharedProps } from '../types';

const COLS = 3;
const TODAY_YEAR = new Date().getFullYear();

type YearGridViewProps = ViewSharedProps & {
  selectionType: CalendarSelectionType;
  value?: DateValue | DateValue[] | DateRange;
  onChange?: (value: DateValue | DateValue[] | DateRange) => void;
};

function getSelectedYears(
  selectionType: CalendarSelectionType,
  value?: DateValue | DateValue[] | DateRange
): number[] {
  if (selectionType === 'range') {
    const range = value as DateRange | undefined;
    const years: number[] = [];
    const from = toDateOrUndefined(range?.from);
    const to = toDateOrUndefined(range?.to);
    if (from) years.push(from.getFullYear());
    if (to) years.push(to.getFullYear());
    return years;
  }
  if (selectionType === 'multiple') {
    const dates = (value as DateValue[] | undefined) ?? [];
    return dates
      .map((d) => toDateOrUndefined(d)?.getFullYear())
      .filter((y): y is number => y != null);
  }
  const single = toDateOrUndefined(value as DateValue);
  return single ? [single.getFullYear()] : [];
}

function getRangeEndpoints(value?: DateValue | DateValue[] | DateRange) {
  const range = value as DateRange | undefined;
  return {
    from: toDateOrUndefined(range?.from)?.getFullYear(),
    to: toDateOrUndefined(range?.to)?.getFullYear(),
  };
}

export function YearGridView({
  navDate,
  onNavDateChange,
  selectionType,
  value,
  onChange,
  minDate,
  maxDate,
  disabled,
  readOnly,
}: YearGridViewProps) {
  const decadeStart = getDecadeStart(navDate.getFullYear());
  const years = getDecadeYears(decadeStart);
  const selectedYears = getSelectedYears(selectionType, value);
  const { from: rangeFrom, to: rangeTo } =
    selectionType === 'range' ? getRangeEndpoints(value) : {};

  const isYearDisabled = (year: number) => {
    if (maxDate && year > maxDate.getFullYear()) return true;
    if (minDate && year < minDate.getFullYear()) return true;
    return false;
  };

  const handleYearClick = (year: number) => {
    if (disabled || readOnly || isYearDisabled(year)) return;
    const date = new Date(year, 0, 1);

    if (selectionType === 'single') {
      const currentYear = toDateOrUndefined(value as DateValue)?.getFullYear();
      onChange?.(currentYear === year ? undefined : date);
    } else if (selectionType === 'multiple') {
      const current = (value as DateValue[] | undefined) ?? [];
      const exists = current.some((d) => toDateOrUndefined(d)?.getFullYear() === year);
      onChange?.(
        exists
          ? current.filter((d) => toDateOrUndefined(d)?.getFullYear() !== year)
          : [...current, date]
      );
    } else {
      const range = (value as DateRange | undefined) ?? { from: undefined, to: undefined };
      const from = toDateOrUndefined(range.from);
      const to = toDateOrUndefined(range.to);
      if (!from || (from && to)) {
        onChange?.({ from: date, to: undefined });
      } else {
        onChange?.({ from: date < from ? date : from, to: date < from ? from : date });
      }
    }
  };

  // Split years into rows of COLS
  const rows: number[][] = [];
  for (let i = 0; i < years.length; i += COLS) {
    rows.push(years.slice(i, i + COLS));
  }

  return (
    <div className="w-full p-3">
      <ViewHeader
        title={`${years[0]} – ${years[years.length - 1]}`}
        onPrev={() => onNavDateChange(new Date(decadeStart - 10, navDate.getMonth(), 1))}
        onNext={() => onNavDateChange(new Date(decadeStart + 10, navDate.getMonth(), 1))}
        prevLabel="Previous decade"
        nextLabel="Next decade"
      />

      <div className="mt-3 flex flex-col gap-1">
        {rows.map((row, rowIdx) => (
          <div key={`row-${rowIdx}`} className="flex gap-1">
            {row.map((year) => {
              const isSelected = selectedYears.includes(year);
              const isToday = year === TODAY_YEAR;
              const isInRange =
                selectionType === 'range' && isYearInRange(year, rangeFrom, rangeTo);
              const isRangeStart = selectionType === 'range' && year === rangeFrom;
              const isRangeEnd = selectionType === 'range' && year === rangeTo;
              const isEndpoint = isRangeStart || isRangeEnd;
              const isDisabled = isYearDisabled(year);

              return (
                <button
                  key={year}
                  type="button"
                  onClick={() => handleYearClick(year)}
                  disabled={isDisabled || disabled}
                  className={cn(
                    'relative flex h-9 flex-1 items-center justify-center rounded-md font-normal text-sm transition-colors',
                    'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1',
                    'disabled:pointer-events-none disabled:opacity-40',
                    // Range highlight (background strip, endpoints get overridden below)
                    isInRange && !isEndpoint && 'rounded-none bg-accent text-accent-foreground',
                    isRangeStart && 'rounded-r-none',
                    isRangeEnd && 'rounded-l-none',
                    // Selection
                    isSelected
                      ? 'bg-primary text-primary-foreground hover:bg-primary/90'
                      : isInRange && !isEndpoint
                        ? 'hover:bg-accent/80'
                        : 'hover:bg-accent hover:text-accent-foreground',
                    // Today indicator (when not selected)
                    isToday && !isSelected && 'font-semibold text-primary'
                  )}
                >
                  {year}
                  {/* Today dot */}
                  {isToday && !isSelected && (
                    <span className="absolute bottom-1 left-1/2 size-1 -translate-x-1/2 rounded-full bg-primary" />
                  )}
                </button>
              );
            })}
            {/* Fill empty cells in last row so range strip spans correctly */}
            {row.length < COLS &&
              Array.from({ length: COLS - row.length }).map((_, i) => (
                <div key={`empty-${i}`} className="flex-1" />
              ))}
          </div>
        ))}
      </div>
    </div>
  );
}

YearGridView.displayName = 'YearGridView';

